// The update log (updates.ts) in every language: updates 12 to 22. See updates.ts in this folder.
import type { Row } from "./table.ts";

export const UPDATES2: Readonly<Record<string, Row>> = {
  "Fernwick, crossbows, war bows and Hazel's quiver": ["ファーンウィック、クロスボウ、ウォーボウ、ヘイゼルの矢筒", "펀윅, 석궁, 전쟁활, 헤이즐의 화살통", "蕨村、弩、战弓与黑兹尔的箭袋", "蕨村、弩、戰弓與黑茲爾的箭袋", "Fernwick, nỏ, cung chiến và ống tên của Hazel", "Fernwick, busur silang, busur perang, dan tabung panah Hazel", "เฟิร์นวิก หน้าไม้ ธนูศึก และกระบอกธนูของเฮเซล", "Fernwick, arbaletler, savaş yayları ve Hazel'in sadağı", "Fernwick, ballestas, arcos de guerra y el carcaj de Hazel", "Fernwick, bestas, arcos de guerra e a aljava da Hazel", "Фернвик, арбалеты, боевые луки и колчан Хейзел", "Фернвік, арбалети, бойові луки й сагайдак Гейзел"],
  "Fernwick, a woodcutters' village in the heart of Whisperwood (take the woods road west from the Ashen mine): Hazel's War Bows, the Timber Yard (the best price for logs, and axes), a bank, cottages, a willow pond and archery butts.": ["ささやきの森の中心にある木こりの村、ファーンウィック（Ashen 鉱山から森の道を西へ）：ヘイゼルの戦弓店、Timber Yard（丸太の最高値買い取りと斧）、銀行、小屋、柳の池、弓の的場。", "속삭임숲 한가운데의 나무꾼 마을 펀윅(Ashen 광산에서 숲길을 따라 서쪽으로): 헤이즐의 전투용 활, Timber Yard(통나무 최고가 매입과 도끼), 은행, 오두막, 버드나무 연못, 활터.", "蕨村，低语林中心的伐木村（从 Ashen 矿沿林间路向西）：黑兹尔战弓铺、Timber Yard（原木收购价最高，还卖斧头）、银行、小屋、柳树池塘和箭靶。", "蕨村，低語林中心的伐木村（從 Ashen 礦沿林間路向西）：黑茲爾戰弓鋪、Timber Yard（原木收購價最高，還賣斧頭）、銀行、小屋、柳樹池塘和箭靶。", "Fernwick, làng tiều phu giữa lòng Whisperwood (đi đường rừng về phía tây từ mỏ Ashen): Cung chiến của Hazel, Timber Yard (giá gỗ tốt nhất, và rìu), ngân hàng, nhà tranh, ao liễu và bia bắn cung.", "Fernwick, desa penebang kayu di jantung Whisperwood (ambil jalan hutan ke barat dari tambang Ashen): Busur Perang Hazel, Timber Yard (harga terbaik untuk kayu, dan kapak), bank, pondok, kolam dedalu, dan sasaran panahan.", "เฟิร์นวิก หมู่บ้านคนตัดไม้กลางป่ากระซิบ (ไปตามทางป่าทิศตะวันตกจากเหมือง Ashen): ธนูศึกของเฮเซล Timber Yard (ราคาท่อนไม้ดีที่สุด และขวาน) ธนาคาร กระท่อม บ่อต้นหลิว และเป้ายิงธนู", "Whisperwood'un kalbinde bir oduncu köyü olan Fernwick (Ashen madeninden orman yolundan batıya): Hazel'in Savaş Yayları, Timber Yard (kütüklere en iyi fiyat ve baltalar), bir banka, kulübeler, söğütlü bir gölet ve okçuluk hedefleri.", "Fernwick, una aldea de leñadores en el corazón de Whisperwood (toma el camino del bosque hacia el oeste desde la mina Ashen): Arcos de guerra de Hazel, el Timber Yard (el mejor precio por troncos, y hachas), un banco, casitas, un estanque con sauces y dianas de tiro.", "Fernwick, uma vila de lenhadores no coração de Whisperwood (pegue a estrada da mata a oeste da mina Ashen): Arcos de Guerra da Hazel, o Timber Yard (o melhor preço por toras, e machados), um banco, chalés, um lago de salgueiros e alvos de tiro.", "Фернвик — деревня лесорубов в сердце Шепчущего леса (лесной дорогой на запад от рудника Ashen): Боевые луки Хейзел, Timber Yard (лучшая цена за брёвна и топоры), банк, домики, пруд с ивами и мишени для стрельбы.", "Фернвік — село лісорубів у серці Шепітливого лісу (лісовою дорогою на захід від копальні Ashen): Бойові луки Гейзел, Timber Yard (найкраща ціна за колоди й сокири), банк, хатинки, ставок із вербами та мішені для стрільби."],
  "Crossbows in six tiers: metal limbs from the anvil (two bars) on a stock carved from logs, fitted together with Crafting. Pewter on a wooden stock, blackiron and ashsteel on oak, moonsilver on willow, glimmer on maple, rarite on yew. Or buy the first few at Fletch & Feather.": ["クロスボウは6段階：金床で作る金属の弓身（延べ棒2本）を丸太から彫った台座に、工芸で組み合わせます。ピューターは木の台座、ブラックアイアンとアッシュスチールはオーク、ムーンシルバーは柳、グリマーはカエデ、レアライトはイチイ。最初のいくつかはフレッチ&フェザーでも買えます。", "석궁은 6단계: 모루에서 만든 금속 활몸(주괴 2개)을 통나무로 깎은 개머리에 공예로 결합합니다. 백랍은 나무 개머리, 흑철과 잿빛강철은 참나무, 월은은 버드나무, 글리머는 단풍나무, 레어라이트는 주목. 처음 몇 개는 플레치 앤 페더에서 살 수도 있습니다.", "弩分六个等级：用铁砧打出的金属弩臂（两块锭）装在原木雕成的弩托上，用手工组装。白镴配木托，黑铁和灰钢配橡木，月银配柳木，微光配枫木，稀晶配紫杉。前几种也可以在箭羽铺买到。", "弩分六個等級：用鐵砧打出的金屬弩臂（兩塊錠）裝在原木雕成的弩托上，用手工組裝。白鑞配木托，黑鐵和灰鋼配橡木，月銀配柳木，微光配楓木，稀晶配紫杉。前幾種也可以在箭羽鋪買到。", "Nỏ có sáu bậc: cánh nỏ kim loại rèn trên đe (hai thỏi) lắp lên báng khắc từ gỗ, ghép bằng Thủ công. Thiếc trên báng gỗ, sắt đen và thép tro trên gỗ sồi, bạc trăng trên gỗ liễu, ánh kim trên gỗ phong, rarit trên gỗ thủy tùng. Hoặc mua vài cái đầu ở Fletch & Feather.", "Busur silang dalam enam tingkat: lengan logam dari landasan (dua batangan) pada popor yang diukir dari kayu, dirakit dengan Kerajinan. Timah pada popor kayu, besi hitam dan baja abu pada ek, perak bulan pada dedalu, kemilau pada maple, rarit pada yew. Atau beli beberapa yang pertama di Fletch & Feather.", "หน้าไม้หกระดับ: แขนโลหะจากทั่ง (สองแท่ง) บนพานท้ายที่แกะจากท่อนไม้ ประกอบด้วยงานฝีมือ ดีบุกบนพานไม้ เหล็กดำและเหล็กเถ้าบนไม้โอ๊ก เงินจันทร์บนไม้หลิว ประกายแสงบนไม้เมเปิล แรไรต์บนไม้ยู หรือซื้อสองสามอันแรกที่เฟล็ตช์แอนด์เฟเธอร์", "Altı kademe arbalet: örste yapılan metal kollar (iki külçe), kütükten oyulmuş bir kundağa Zanaat ile takılır. Kalay ahşap kundakta, kara demir ve kül çeliği meşede, ay gümüşü söğütte, parıltı akçaağaçta, rarit porsukta. Ya da ilk birkaçını Fletch & Feather'dan al.", "Ballestas en seis niveles: palas de metal del yunque (dos lingotes) sobre una culata tallada de troncos, montadas con Artesanía. Peltre en culata de madera, hierro negro y acero ceniza en roble, plata lunar en sauce, destello en arce, rarita en tejo. O compra las primeras en Fletch & Feather.", "Bestas em seis níveis: braços de metal da bigorna (duas barras) numa coronha entalhada de toras, montados com Artesanato. Estanho em coronha de madeira, ferro negro e aço cinzento em carvalho, prata lunar em salgueiro, lampejo em bordo, rarita em teixo. Ou compre as primeiras na Fletch & Feather.", "Арбалеты шести уровней: металлические плечи с наковальни (два слитка) на ложе, вырезанном из брёвен, собранные Ремеслом. Олово на деревянном ложе, чёрное железо и пепельная сталь на дубе, лунное серебро на иве, мерцалит на клёне, рарит на тисе. Или купите первые в «Стреле и пере».", "Арбалети шести рівнів: металеві плечі з ковадла (два злитки) на ложі, вирізаному з колод, зібрані Ремеслом. Олово на дерев'яному ложі, чорне залізо й попеляста сталь на дубі, місячне срібло на вербі, мерехтит на клені, рарит на тисі. Або купіть перші в «Стрілі й пері»."],
  "Crossbows fire bolts (a dozen unfeathered bolts from a bar, then feathers), shoot slower than bows and hit harder, and they're one-handed, so you can carry a shield.": ["クロスボウはボルトを撃ちます（延べ棒1本から羽なしボルト12本、その後に羽根）。弓より遅く、威力は高く、片手持ちなので盾も持てます。", "석궁은 볼트를 쏩니다(주괴 하나로 깃 없는 볼트 12개, 그다음 깃털). 활보다 느리지만 더 세고, 한손 무기라 방패를 들 수 있습니다.", "弩发射弩箭（一块锭做十二支无羽弩箭，再装羽毛），射速比弓慢但威力更大，而且是单手武器，可以同时持盾。", "弩發射弩箭（一塊錠做十二支無羽弩箭，再裝羽毛），射速比弓慢但威力更大，而且是單手武器，可以同時持盾。", "Nỏ bắn tên nỏ (một thỏi ra mười hai mũi chưa gắn lông, rồi gắn lông), bắn chậm hơn cung nhưng mạnh hơn, và cầm một tay nên có thể mang khiên.", "Busur silang menembakkan bolt (selusin bolt tanpa bulu dari satu batangan, lalu bulu), lebih lambat dari busur tapi lebih keras, dan satu tangan, jadi bisa membawa perisai.", "หน้าไม้ยิงโบลต์ (โบลต์ไม่มีขนสิบสองดอกจากหนึ่งแท่ง แล้วติดขน) ยิงช้ากว่าธนูแต่แรงกว่า และถือมือเดียว จึงถือโล่ได้", "Arbaletler cıvata atar (bir külçeden on iki tüysüz cıvata, sonra tüyler), yaydan yavaş ama daha sert vurur ve tek ellidir, yani kalkan taşıyabilirsin.", "Las ballestas disparan virotes (una docena sin plumas por lingote, luego las plumas), disparan más despacio que los arcos y pegan más fuerte, y son de una mano, así que puedes llevar escudo.", "As bestas disparam virotes (uma dúzia sem penas por barra, depois as penas), atiram mais devagar que arcos e batem mais forte, e são de uma mão, então dá pra usar escudo.", "Арбалеты стреляют болтами (дюжина болтов без оперения из слитка, затем перья), бьют медленнее луков, но сильнее, и они одноручные — можно носить щит.", "Арбалети стріляють болтами (дюжина болтів без оперення зі злитка, потім пір'я), б'ють повільніше за луки, але сильніше, і вони одноручні — можна носити щит."],
  "War bows: a heavier bow for every wood, from two logs. Slower to draw, harder hitting, and a tile more reach. The plain war bow needs Ranged 5, and only Hazel sells them.": ["ウォーボウ：木材ごとの重い弓で、丸太2本から作ります。引くのは遅いけれど威力が高く、射程が1マス長い。普通のウォーボウは遠隔5が必要で、売っているのはヘイゼルだけ。", "전쟁활: 나무마다 있는 더 무거운 활로, 통나무 두 개로 만듭니다. 당기기는 느리지만 더 세고, 사거리가 한 칸 깁니다. 기본 전쟁활은 원거리 5가 필요하고, 헤이즐만 팝니다.", "战弓：每种木材都有更重的弓，用两根原木制作。拉弓更慢，威力更大，射程多一格。普通战弓需要远程 5 级，只有黑兹尔有卖。", "戰弓：每種木材都有更重的弓，用兩根原木製作。拉弓更慢，威力更大，射程多一格。普通戰弓需要遠端 5 級，只有黑茲爾有賣。", "Cung chiến: cung nặng hơn cho mỗi loại gỗ, làm từ hai khúc gỗ. Kéo chậm hơn, mạnh hơn, và tầm xa thêm một ô. Cung chiến thường cần Tầm xa 5, và chỉ Hazel bán.", "Busur perang: busur lebih berat untuk setiap kayu, dari dua batang kayu. Lebih lambat ditarik, lebih keras, dan jangkauan satu petak lebih jauh. Busur perang biasa butuh Jarak jauh 5, dan hanya Hazel yang menjualnya.", "ธนูศึก: ธนูที่หนักกว่าสำหรับไม้ทุกชนิด ทำจากท่อนไม้สองท่อน ง้างช้ากว่า แรงกว่า และระยะไกลขึ้นหนึ่งช่อง ธนูศึกธรรมดาต้องใช้ระยะไกล 5 และมีแค่เฮเซลที่ขาย", "Savaş yayları: her ağaç için iki kütükten daha ağır bir yay. Germesi yavaş, vuruşu sert, menzili bir kare fazla. Düz savaş yayı Menzilli 5 ister ve onları yalnızca Hazel satar.", "Arcos de guerra: un arco más pesado para cada madera, con dos troncos. Más lentos de tensar, pegan más fuerte y alcanzan una casilla más. El arco de guerra simple pide A distancia 5, y solo Hazel los vende.", "Arcos de guerra: um arco mais pesado para cada madeira, com duas toras. Mais lentos de puxar, batem mais forte e alcançam um bloco a mais. O arco de guerra simples pede À distância 5, e só a Hazel vende.", "Боевые луки: более тяжёлый лук для каждой древесины, из двух брёвен. Медленнее натягиваются, бьют сильнее и дальше на клетку. Простой боевой лук требует Стрельбу 5, и продаёт их только Хейзел.", "Бойові луки: важчий лук для кожної деревини, з двох колод. Повільніше натягуються, б'ють сильніше й далі на клітинку. Простий бойовий лук потребує Стрільби 5, і продає їх лише Гейзел."],
  "New quest, Hazel's Quiver: win her grandmother's quiver back from the Grumblin chief and she'll mend it for you. Worn on your back, it calls four in five arrows and bolts straight back to your pack.": ["新クエスト「ヘーゼルの矢筒」：グランブリンの族長から彼女の祖母の矢筒を取り返せば、直してくれます。背負うと、矢とボルトの5本に4本がまっすぐ荷物に戻ってきます。", "새 퀘스트 「헤이즐의 화살통」: 그럼블린 족장에게서 할머니의 화살통을 되찾아 주면 수리해 줍니다. 등에 메면 화살과 볼트 다섯 중 넷이 곧장 가방으로 돌아옵니다.", "新任务「黑泽尔的箭袋」：从嘟囔怪首领手中夺回她祖母的箭袋，她会帮你修好。背在身后，五支箭和弩箭中有四支会直接飞回你的背包。", "新任務「黑澤爾的箭袋」：從嘟囔怪首領手中奪回她祖母的箭袋，她會幫你修好。背在身後，五支箭和弩箭中有四支會直接飛回你的背包。", "Nhiệm vụ mới, Ống tên của Hazel: giành lại ống tên của bà cô ấy từ tù trưởng Grumblin và cô ấy sẽ sửa nó cho bạn. Đeo trên lưng, nó gọi bốn trên năm mũi tên và tên nỏ bay thẳng về túi.", "Misi baru, Tabung Panah Hazel: rebut kembali tabung panah neneknya dari kepala suku Grumblin dan ia akan memperbaikinya untukmu. Dipakai di punggung, ia memanggil empat dari lima panah dan bolt kembali ke tasmu.", "เควสต์ใหม่ กระบอกธนูของเฮเซล: ชิงกระบอกธนูของยายเธอคืนจากหัวหน้ากรัมบลิน แล้วเธอจะซ่อมให้ สะพายไว้ที่หลัง ลูกศรและโบลต์สี่ในห้าดอกจะกลับเข้ากระเป๋าทันที", "Yeni görev, Hazel'in Sadağı: büyükannesinin sadağını Grumblin şefinden geri al, o da senin için onarsın. Sırtında taşındığında, okların ve cıvataların beşte dördünü doğrudan çantana geri çağırır.", "Nueva misión, El carcaj de Hazel: recupera el carcaj de su abuela del jefe Grumblin y ella te lo arreglará. Llevado a la espalda, devuelve cuatro de cada cinco flechas y virotes directamente a tu mochila.", "Nova missão, A Aljava de Hazel: recupere a aljava da avó dela com o chefe Grumblin e ela conserta pra você. Usada nas costas, devolve quatro em cada cinco flechas e virotes direto pra sua mochila.", "Новый квест «Колчан Хейзел»: отбейте колчан её бабушки у вождя грамблинов, и она починит его для вас. На спине он возвращает четыре из пяти стрел и болтов прямо в сумку.", "Новий квест «Сагайдак Гейзел»: відбийте сагайдак її бабусі у вождя грамблінів, і вона полагодить його для вас. На спині він повертає чотири з п'яти стріл і болтів просто в сумку."],
  "The Thought altar has moved out of Fernwick's street to a quiet glade north-east of the village, beside the road to Wyrmreach.": ["思念の祭壇はファーンウィックの通りから、村の北東、ワームリーチへの道沿いにある静かな空き地へ移りました。", "사념 제단이 펀윅 거리에서 마을 북동쪽, 웜리치로 가는 길가의 조용한 숲속 빈터로 옮겨졌습니다.", "思绪祭坛已从蕨村街上搬到村子东北方、通往龙域路边的一片幽静林间空地。", "思緒祭壇已從蕨村街上搬到村子東北方、通往龍域路邊的一片幽靜林間空地。", "Bàn thờ Tư Tưởng đã rời phố Fernwick đến một khoảng rừng yên tĩnh ở đông bắc làng, cạnh đường tới Wyrmreach.", "Altar Pikiran pindah dari jalan Fernwick ke lapangan hutan yang tenang di timur laut desa, di samping jalan ke Wyrmreach.", "แท่นบูชาความคิดย้ายออกจากถนนของเฟิร์นวิกไปยังลานป่าเงียบสงบทางตะวันออกเฉียงเหนือของหมู่บ้าน ข้างทางไปเวิร์มรีช", "Düşünce sunağı Fernwick'in sokağından köyün kuzeydoğusundaki, Wyrmreach yolunun yanındaki sessiz bir açıklığa taşındı.", "El Altar de Pensamiento se ha mudado de la calle de Fernwick a un claro tranquilo al noreste de la aldea, junto al camino a Wyrmreach.", "O Altar de Pensamento saiu da rua de Fernwick para uma clareira tranquila a nordeste da vila, ao lado da estrada para Wyrmreach.", "Алтарь Мысли переехал с улицы Фернвика на тихую поляну к северо-востоку от деревни, у дороги в Вирмрич.", "Вівтар Думки переїхав із вулиці Фернвіка на тиху галявину на північний схід від села, біля дороги до Вірмріча."],
  "Softer rain, clearer settings": ["やわらかな雨と見やすい設定", "더 부드러운 비, 더 깔끔한 설정", "更柔和的雨声，更清晰的设置", "更柔和的雨聲，更清晰的設定", "Mưa êm hơn, cài đặt rõ hơn", "Hujan lebih lembut, pengaturan lebih jelas", "ฝนนุ่มขึ้น การตั้งค่าชัดขึ้น", "Daha yumuşak yağmur, daha net ayarlar", "Lluvia más suave y ajustes más claros", "Chuva mais suave, configurações mais claras", "Мягче дождь, понятнее настройки", "М'якший дощ, зрозуміліші налаштування"],
  "Rain is now a soft, steady wash of sound that swells and fades with the weather, instead of a ticking hiss that sounded like footsteps.": ["雨の音は、足音のように聞こえたカチカチというノイズではなく、天気に合わせて強まったり弱まったりする、やわらかく安定した音になりました。", "빗소리가 발소리처럼 들리던 똑딱거리는 쉿 소리 대신, 날씨에 따라 커지고 잦아드는 부드럽고 꾸준한 소리가 되었습니다.", "雨声不再是像脚步声一样的滴答嘶嘶声，而是随天气起伏、柔和而持续的声响。", "雨聲不再是像腳步聲一樣的滴答嘶嘶聲，而是隨天氣起伏、柔和而持續的聲響。", "Tiếng mưa giờ là âm thanh êm, đều, to dần và nhỏ dần theo thời tiết, thay vì tiếng xì lách tách nghe như tiếng bước chân.", "Hujan kini berupa suara lembut dan stabil yang membesar dan memudar mengikuti cuaca, bukan desis berdetak yang terdengar seperti langkah kaki.", "เสียงฝนตอนนี้เป็นเสียงนุ่มสม่ำเสมอที่ดังขึ้นและเบาลงตามสภาพอากาศ แทนเสียงฟู่ติ๊กๆ ที่ฟังเหมือนเสียงฝีเท้า", "Yağmur artık ayak sesine benzeyen tıkırtılı bir hışırtı değil, havayla birlikte yükselip alçalan yumuşak, düzenli bir ses.", "La lluvia es ahora un rumor suave y constante que crece y se apaga con el tiempo, en vez de un siseo con tictac que sonaba a pasos.", "A chuva agora é um som suave e constante que cresce e some com o tempo, em vez de um chiado com tique-taque que parecia passos.", "Дождь теперь — мягкий ровный шум, который нарастает и стихает вместе с погодой, а не тикающее шипение, похожее на шаги.", "Дощ тепер — м'який рівний шум, що наростає й стихає разом із погодою, а не цокітливе шипіння, схоже на кроки."],
  "Settings has pixel sliders for music, effects and zoom (with their values shown), and the Graphics choice (Auto, High, Low) is easy to read.": ["設定に音楽、効果音、ズームのピクセルスライダー（値も表示）を追加し、グラフィック（自動・高・低）の選択も見やすくなりました。", "설정에 음악, 효과음, 확대용 픽셀 슬라이더(값 표시)가 생겼고, 그래픽 선택(자동, 높음, 낮음)도 읽기 쉬워졌습니다.", "设置中有音乐、音效和缩放的像素滑块（显示数值），图形选项（自动、高、低）也更易读了。", "設定中有音樂、音效和縮放的像素滑桿（顯示數值），圖形選項（自動、高、低）也更易讀了。", "Cài đặt có thanh trượt pixel cho nhạc, hiệu ứng và thu phóng (hiện giá trị), và lựa chọn Đồ họa (Tự động, Cao, Thấp) dễ đọc.", "Pengaturan punya penggeser piksel untuk musik, efek, dan zoom (dengan nilainya), dan pilihan Grafis (Otomatis, Tinggi, Rendah) mudah dibaca.", "การตั้งค่ามีแถบเลื่อนพิกเซลสำหรับเพลง เอฟเฟกต์ และการซูม (แสดงค่า) และตัวเลือกกราฟิก (อัตโนมัติ สูง ต่ำ) อ่านง่าย", "Ayarlarda müzik, efekt ve yakınlaştırma için piksel kaydırıcılar var (değerleriyle) ve Grafik seçimi (Otomatik, Yüksek, Düşük) kolay okunuyor.", "Los ajustes tienen deslizadores pixelados para música, efectos y zoom (con su valor), y la opción de Gráficos (Auto, Alto, Bajo) se lee con facilidad.", "As configurações têm controles em pixel para música, efeitos e zoom (com os valores) e a opção de Gráficos (Auto, Alto, Baixo) é fácil de ler.", "В настройках есть пиксельные ползунки для музыки, эффектов и масштаба (со значениями), а выбор графики (Авто, Высокая, Низкая) легко читается.", "У налаштуваннях є піксельні повзунки для музики, ефектів і масштабу (зі значеннями), а вибір графіки (Авто, Висока, Низька) легко читається."],
  "Redrawn food, bones and ores": ["食べ物、骨、鉱石を描き直し", "음식, 뼈, 광석 새로 그림", "重绘食物、骨头与矿石", "重繪食物、骨頭與礦石", "Vẽ lại thức ăn, xương và quặng", "Makanan, tulang, dan bijih digambar ulang", "วาดอาหาร กระดูก และแร่ใหม่", "Yeniden çizilen yiyecekler, kemikler ve cevherler", "Comida, huesos y minerales redibujados", "Comida, ossos e minérios redesenhados", "Перерисованы еда, кости и руда", "Перемальовано їжу, кістки й руду"],
  "Every fish has its own look: minnows swim in a little school, perch are striped, carp are golden and scaly, char have red bellies, grayling and sailfish raise their tall fins, the inkshark is a shark and the inkcrab is a crab.": ["魚ごとに見た目が違います：小魚は小さな群れで泳ぎ、パーチは縞模様、鯉は金色で鱗があり、イワナは腹が赤く、カワヒメマスとバショウカジキは高いひれを立て、インクザメはサメ、インクガニはカニです。", "물고기마다 모습이 다릅니다: 피라미는 작은 떼로 헤엄치고, 농어는 줄무늬, 잉어는 금빛 비늘, 곤들매기는 배가 붉고, 사루기와 돛새치는 높은 지느러미를 세우며, 먹물상어는 상어, 먹물게는 게입니다.", "每种鱼都有自己的样子：小鱼成群游动，鲈鱼有条纹，鲤鱼金黄带鳞，红点鲑腹部发红，茴鱼和旗鱼竖起高高的鳍，墨鲨是鲨鱼，墨蟹是螃蟹。", "每種魚都有自己的樣子：小魚成群游動，鱸魚有條紋，鯉魚金黃帶鱗，紅點鮭腹部發紅，茴魚和旗魚豎起高高的鰭，墨鯊是鯊魚，墨蟹是螃蟹。", "Mỗi loài cá có vẻ ngoài riêng: cá tuế bơi thành đàn nhỏ, cá rô có sọc, cá chép vàng óng có vảy, cá hồi chấm bụng đỏ, cá hồi xám và cá cờ dựng vây cao, cá mập mực là cá mập và cua mực là cua.", "Setiap ikan punya tampilannya sendiri: ikan kecil berenang berkelompok, perch bergaris, ikan mas keemasan bersisik, char berperut merah, grayling dan layaran menegakkan sirip tinggi, hiu tinta adalah hiu dan kepiting tinta adalah kepiting.", "ปลาแต่ละชนิดมีรูปลักษณ์ของตัวเอง: ปลาซิวว่ายเป็นฝูงเล็ก ปลาเพิร์ชมีลาย ปลาคาร์ปสีทองมีเกล็ด ปลาชาร์ท้องแดง ปลาเกรย์ลิงและปลากระโทงชูครีบสูง ฉลามหมึกเป็นฉลาม และปูหมึกเป็นปู", "Her balığın kendi görünüşü var: gümüş balıkları küçük bir sürü hâlinde yüzer, levrekler çizgili, sazanlar altın renkli ve pullu, alabalıkların karnı kırmızı, kılçıkbalığı ve yelken balığı uzun yüzgeçlerini kaldırır, mürekkep köpekbalığı köpekbalığı, mürekkep yengeci yengeç.", "Cada pez tiene su aspecto: los pececillos nadan en un pequeño banco, las percas tienen rayas, las carpas son doradas y escamosas, los salvelinos tienen la tripa roja, el tímalo y el pez vela alzan sus altas aletas, el tiburón de tinta es un tiburón y el cangrejo de tinta es un cangrejo.", "Cada peixe tem sua aparência: os peixinhos nadam num pequeno cardume, as percas são listradas, as carpas são douradas e escamosas, as trutas-árticas têm barriga vermelha, o tímalo e o peixe-vela erguem as nadadeiras altas, o tubarão-tinta é um tubarão e o caranguejo-tinta é um caranguejo.", "У каждой рыбы свой вид: мальки плавают стайкой, окуни полосатые, карпы золотистые и чешуйчатые, у гольцов красное брюхо, хариус и парусник поднимают высокие плавники, чернильная акула — акула, а чернильный краб — краб.", "Кожна риба має свій вигляд: мальки плавають зграйкою, окуні смугасті, коропи золотисті й лускаті, у гольців червоне черево, харіус і вітрильник піднімають високі плавці, чорнильна акула — акула, а чорнильний краб — краб."],
  "Chicken is a drumstick and beef is a steak with a rim of fat. Cooked food is browned with grill marks, and burnt food is a charred lump with a wisp of smoke.": ["鶏肉は骨付きもも肉、牛肉は脂身の縁があるステーキに。調理した食べ物は焼き色と焼き目がつき、焦げた食べ物は煙が一筋立つ炭の塊です。", "닭고기는 닭다리, 소고기는 기름 테두리가 있는 스테이크입니다. 요리한 음식은 노릇하게 그릴 자국이 있고, 탄 음식은 연기 한 줄기가 오르는 숯덩이입니다.", "鸡肉是鸡腿，牛肉是带一圈肥边的牛排。熟食烤得焦黄带烤痕，烤焦的食物是一团冒着一缕烟的焦炭。", "雞肉是雞腿，牛肉是帶一圈肥邊的牛排。熟食烤得焦黃帶烤痕，烤焦的食物是一團冒著一縷煙的焦炭。", "Thịt gà là đùi gà, thịt bò là miếng bít tết có viền mỡ. Đồ nấu chín vàng nâu có vết nướng, còn đồ cháy là cục than bốc khói.", "Ayam adalah paha ayam dan daging sapi adalah steik dengan pinggiran lemak. Makanan matang kecokelatan dengan bekas panggangan, dan makanan gosong berupa gumpalan hangus dengan kepulan asap.", "ไก่เป็นน่องไก่ และเนื้อวัวเป็นสเต็กมีขอบไขมัน อาหารสุกมีสีน้ำตาลพร้อมรอยย่าง ส่วนอาหารไหม้เป็นก้อนดำมีควันลอย", "Tavuk bir but, sığır eti yağ kenarlı bir biftek. Pişmiş yemek ızgara izleriyle kızarmış, yanık yemek ise bir tutam dumanı olan kömürleşmiş bir topak.", "El pollo es un muslo y la ternera es un filete con borde de grasa. La comida cocinada está dorada con marcas de parrilla, y la quemada es un pegote carbonizado con una voluta de humo.", "O frango é uma coxa e a carne é um bife com borda de gordura. A comida cozida fica dourada com marcas de grelha, e a queimada é um toco carbonizado com um fio de fumaça.", "Курица — это ножка, говядина — стейк с каёмкой жира. Готовая еда подрумянена с полосками гриля, а подгоревшая — обугленный комок с дымком.", "Курятина — це ніжка, яловичина — стейк з облямівкою жиру. Готова їжа підрум'янена зі смужками гриля, а підгоріла — обвуглена грудка з димком."],
  "Bones, large bones, ink bones and drake bones each look different, and every ore shows its own metal: dull pewter, rusty blackiron, glossy inkcoal, silver-veined moonsilver, glimmer and rarite crystals, and soft clay.": ["骨、大きな骨、インクの骨、ドレイクの骨の見た目がそれぞれ違い、鉱石も金属ごとの姿に：くすんだピューター、錆びたブラックアイアン、つややかなインク炭、銀の筋が入ったムーンシルバー、グリマーとレアライトの結晶、やわらかい粘土。", "뼈, 큰 뼈, 먹물 뼈, 드레이크 뼈가 각각 다르게 생겼고, 광석마다 자기 금속을 보여 줍니다: 칙칙한 백랍, 녹슨 흑철, 윤기 나는 잉크탄, 은빛 결이 있는 월은, 글리머와 레어라이트 결정, 부드러운 점토.", "骨头、大骨头、墨骨和幼龙骨头各不相同，每种矿石都显示自己的金属：暗淡的白镴、生锈的黑铁、光亮的墨炭、带银纹的月银、微光与稀晶晶体，以及柔软的黏土。", "骨頭、大骨頭、墨骨和幼龍骨頭各不相同，每種礦石都顯示自己的金屬：暗淡的白鑞、生鏽的黑鐵、光亮的墨炭、帶銀紋的月銀、微光與稀晶晶體，以及柔軟的黏土。", "Xương, xương lớn, xương mực và xương rồng con đều trông khác nhau, và mỗi quặng hiện kim loại riêng: thiếc xỉn, sắt đen gỉ sét, than mực bóng loáng, bạc trăng có vân bạc, tinh thể ánh kim và rarit, và đất sét mềm.", "Tulang, tulang besar, tulang tinta, dan tulang drake tampak berbeda, dan setiap bijih menunjukkan logamnya: timah kusam, besi hitam berkarat, batu bara tinta mengilap, perak bulan berurat perak, kristal kemilau dan rarit, dan tanah liat lembut.", "กระดูก กระดูกใหญ่ กระดูกหมึก และกระดูกมังกรน้อย หน้าตาต่างกันหมด และแร่แต่ละชนิดแสดงโลหะของตัวเอง: ดีบุกหมอง เหล็กดำขึ้นสนิม ถ่านหมึกมันวาว เงินจันทร์มีลายเงิน ผลึกประกายแสงและแรไรต์ และดินเหนียวนุ่ม", "Kemikler, büyük kemikler, mürekkep kemikleri ve ejderya kemiklerinin her biri farklı görünüyor; her cevher kendi metalini gösteriyor: mat kalay, paslı kara demir, parlak mürekkep kömürü, gümüş damarlı ay gümüşü, parıltı ve rarit kristalleri ve yumuşak kil.", "Los huesos, huesos grandes, huesos de tinta y huesos de draco son distintos, y cada mineral muestra su metal: peltre apagado, hierro negro oxidado, carbón de tinta brillante, plata lunar con vetas plateadas, cristales de destello y rarita, y arcilla blanda.", "Ossos, ossos grandes, ossos de tinta e ossos de draco têm cada um sua aparência, e cada minério mostra seu metal: estanho fosco, ferro negro enferrujado, carvão de tinta lustroso, prata lunar com veios prateados, cristais de lampejo e rarita, e argila macia.", "Кости, большие кости, чернильные кости и кости дрейка выглядят по-разному, а каждая руда показывает свой металл: тусклое олово, ржавое чёрное железо, блестящий чернильный уголь, лунное серебро с серебряными прожилками, кристаллы мерцалита и рарита и мягкая глина.", "Кістки, великі кістки, чорнильні кістки й кістки дрейка виглядають по-різному, а кожна руда показує свій метал: тьмяне олово, іржаве чорне залізо, блискуче чорнильне вугілля, місячне срібло зі срібними прожилками, кристали мерехтиту й рариту та м'яка глина."],
  "Signs, banners and a log out button": ["看板、旗、ログアウトボタン", "간판, 깃발, 로그아웃 버튼", "招牌、旗帜与退出按钮", "招牌、旗幟與登出按鈕", "Biển hiệu, cờ và nút đăng xuất", "Papan nama, spanduk, dan tombol keluar", "ป้าย ธง และปุ่มออกจากระบบ", "Tabelalar, sancaklar ve çıkış düğmesi", "Letreros, estandartes y un botón para salir", "Placas, estandartes e um botão de sair", "Вывески, знамёна и кнопка выхода", "Вивіски, знамена та кнопка виходу"],
  "Every shop and bank has a hanging sign outside its door, painted with what's sold inside (an axe for Axel's, a bow for Fletch & Feather, coins for the banks, a horse for the stables).": ["どの店と銀行にも扉の外に吊り看板があり、中で売っているものが描かれています（Axel's は斧、フレッチ&フェザーは弓、銀行は硬貨、厩舎は馬）。", "모든 상점과 은행 문밖에 안에서 파는 걸 그린 걸이 간판이 있습니다(Axel's는 도끼, 플레치 앤 페더는 활, 은행은 동전, 마구간은 말).", "每家商店和银行门外都挂着招牌，画着里面卖的东西（Axel's 是斧头，箭羽铺是弓，银行是金币，马厩是马）。", "每家商店和銀行門外都掛著招牌，畫著裡面賣的東西（Axel's 是斧頭，箭羽鋪是弓，銀行是金幣，馬廄是馬）。", "Mỗi cửa hàng và ngân hàng đều có biển treo ngoài cửa, vẽ thứ được bán bên trong (rìu cho Axel's, cung cho Fletch & Feather, đồng xu cho ngân hàng, ngựa cho chuồng ngựa).", "Setiap toko dan bank punya papan gantung di luar pintu, bergambar barang yang dijual di dalam (kapak untuk Axel's, busur untuk Fletch & Feather, koin untuk bank, kuda untuk kandang kuda).", "ร้านค้าและธนาคารทุกแห่งมีป้ายแขวนหน้าประตู วาดสิ่งที่ขายข้างใน (ขวานสำหรับ Axel's ธนูสำหรับเฟล็ตช์แอนด์เฟเธอร์ เหรียญสำหรับธนาคาร ม้าสำหรับคอกม้า)", "Her dükkânın ve bankanın kapısının önünde, içeride satılanın resmedildiği asılı bir tabela var (Axel's için balta, Fletch & Feather için yay, bankalar için para, ahırlar için at).", "Cada tienda y banco tiene un letrero colgado en la puerta, pintado con lo que se vende dentro (un hacha para Axel's, un arco para Fletch & Feather, monedas para los bancos, un caballo para los establos).", "Toda loja e banco tem uma placa pendurada na porta, pintada com o que se vende dentro (um machado para a Axel's, um arco para a Fletch & Feather, moedas para os bancos, um cavalo para os estábulos).", "У каждой лавки и банка над дверью висит вывеска с тем, что продаётся внутри (топор у Axel's, лук у «Стрелы и пера», монеты у банков, лошадь у конюшен).", "У кожної крамниці й банку над дверима висить вивіска з тим, що продається всередині (сокира в Axel's, лук у «Стріли й пера», монети в банків, кінь у стаєнь)."],
  "Banners of your own Rare Friend fly around the fountain square and at the castle gate.": ["あなた自身の Rare Friend の旗が、噴水広場の周りと城門にはためきます。", "당신의 Rare Friend가 그려진 깃발이 분수 광장 주변과 성문에서 펄럭입니다.", "你自己的 Rare Friend 旗帜在喷泉广场四周和城门口飘扬。", "你自己的 Rare Friend 旗幟在噴泉廣場四周和城門口飄揚。", "Cờ của chính Rare Friend của bạn tung bay quanh quảng trường đài phun nước và ở cổng lâu đài.", "Spanduk Rare Friend milikmu berkibar di sekitar alun-alun air mancur dan di gerbang kastel.", "ธงของ Rare Friend ของคุณเองโบกสะบัดรอบลานน้ำพุและที่ประตูปราสาท", "Kendi Rare Friend'inin sancakları çeşme meydanının çevresinde ve kale kapısında dalgalanıyor.", "Estandartes de tu propio Rare Friend ondean alrededor de la plaza de la fuente y en la puerta del castillo.", "Estandartes do seu próprio Rare Friend tremulam ao redor da praça da fonte e no portão do castelo.", "Знамёна с вашим собственным Rare Friend развеваются вокруг площади с фонтаном и у ворот замка.", "Знамена з вашим власним Rare Friend майорять довкола площі з фонтаном і біля брами замку."],
  "Save and log out: the ⏻ button by the minimap (or Settings) saves your adventure at once and returns to the title screen, confirming it's safe in this browser.": ["セーブしてログアウト：ミニマップ横の ⏻ ボタン（または設定）で冒険をすぐ保存してタイトル画面に戻り、このブラウザに安全に保存されたことを確認できます。", "저장하고 로그아웃: 미니맵 옆 ⏻ 버튼(또는 설정)을 누르면 모험이 바로 저장되고 타이틀 화면으로 돌아가며, 이 브라우저에 안전하게 저장됐음을 확인해 줍니다.", "保存并退出：小地图旁的 ⏻ 按钮（或设置）会立即保存你的冒险并返回标题画面，并确认已安全保存在此浏览器中。", "保存並登出：小地圖旁的 ⏻ 按鈕（或設定）會立即保存你的冒險並返回標題畫面，並確認已安全保存在此瀏覽器中。", "Lưu và đăng xuất: nút ⏻ cạnh bản đồ nhỏ (hoặc Cài đặt) lưu ngay cuộc phiêu lưu và trở về màn hình tiêu đề, xác nhận nó đã an toàn trong trình duyệt này.", "Simpan dan keluar: tombol ⏻ di samping peta mini (atau Pengaturan) langsung menyimpan petualanganmu dan kembali ke layar judul, memastikan ia aman di peramban ini.", "บันทึกและออก: ปุ่ม ⏻ ข้างมินิแมป (หรือการตั้งค่า) บันทึกการผจญภัยทันทีและกลับสู่หน้าจอหลัก พร้อมยืนยันว่าปลอดภัยในเบราว์เซอร์นี้", "Kaydet ve çık: mini haritanın yanındaki ⏻ düğmesi (ya da Ayarlar) maceranı hemen kaydeder ve başlık ekranına döner, bu tarayıcıda güvende olduğunu onaylar.", "Guardar y salir: el botón ⏻ junto al minimapa (o Ajustes) guarda tu aventura al instante y vuelve a la pantalla de inicio, confirmando que está a salvo en este navegador.", "Salvar e sair: o botão ⏻ ao lado do minimapa (ou Configurações) salva sua aventura na hora e volta à tela inicial, confirmando que está segura neste navegador.", "Сохранить и выйти: кнопка ⏻ у мини-карты (или Настройки) сразу сохраняет приключение и возвращает на титульный экран, подтверждая, что всё сохранено в этом браузере.", "Зберегти й вийти: кнопка ⏻ біля мінімапи (або Налаштування) одразу зберігає пригоду й повертає на титульний екран, підтверджуючи, що все збережено в цьому браузері."],
  "The early levels are a little slower (about half speed at level 1, full speed from level 30), so each level-up means more. Higher levels are unchanged.": ["序盤のレベルは少しゆっくりに（レベル1で約半分の速さ、レベル30から通常の速さ）して、一回一回のレベルアップの価値を高めました。高レベルは変わりません。", "초반 레벨이 조금 느려졌습니다(레벨 1에서 약 절반 속도, 레벨 30부터 정상 속도). 그래서 레벨 업 하나하나가 더 의미 있습니다. 높은 레벨은 그대로입니다.", "前期等级稍微慢了一些（1 级约半速，30 级起全速），所以每次升级更有意义。高等级不变。", "前期等級稍微慢了一些（1 級約半速，30 級起全速），所以每次升級更有意義。高等級不變。", "Các cấp đầu chậm hơn một chút (khoảng nửa tốc độ ở cấp 1, đủ tốc độ từ cấp 30), nên mỗi lần lên cấp ý nghĩa hơn. Cấp cao không đổi.", "Level awal sedikit lebih lambat (sekitar setengah kecepatan di level 1, kecepatan penuh dari level 30), jadi setiap naik level lebih berarti. Level tinggi tidak berubah.", "เลเวลต้นๆ ช้าลงเล็กน้อย (ประมาณครึ่งความเร็วที่เลเวล 1 ความเร็วเต็มตั้งแต่เลเวล 30) ทำให้การเลเวลอัปแต่ละครั้งมีความหมายมากขึ้น เลเวลสูงไม่เปลี่ยน", "İlk seviyeler biraz daha yavaş (1. seviyede yaklaşık yarı hız, 30. seviyeden itibaren tam hız), böylece her seviye atlama daha anlamlı. Yüksek seviyeler değişmedi.", "Los primeros niveles van algo más lentos (a media velocidad en el nivel 1, a velocidad normal desde el 30), así que cada subida significa más. Los niveles altos no cambian.", "Os primeiros níveis são um pouco mais lentos (cerca de metade da velocidade no nível 1, velocidade total a partir do 30), então cada subida vale mais. Os níveis altos não mudaram.", "Первые уровни идут чуть медленнее (около половины скорости на 1-м, полная скорость с 30-го), так что каждый новый уровень значит больше. Высокие уровни не изменились.", "Перші рівні йдуть трохи повільніше (близько половини швидкості на 1-му, повна швидкість із 30-го), тож кожен новий рівень важить більше. Високі рівні не змінилися."],
  "Shields show only on the arm they're worn on: across your body facing one way, tucked behind you facing the other.": ["盾は装着した腕にだけ表示されます：片方を向くと体の前に、反対を向くと背後に隠れます。", "방패는 착용한 팔에만 보입니다: 한쪽을 보면 몸 앞에, 반대쪽을 보면 등 뒤에 숨습니다.", "盾牌只显示在佩戴的那只手臂上：朝一个方向时挡在身前，朝另一个方向时藏在身后。", "盾牌只顯示在佩戴的那隻手臂上：朝一個方向時擋在身前，朝另一個方向時藏在身後。", "Khiên chỉ hiện trên cánh tay đeo nó: chắn ngang người khi quay một hướng, giấu sau lưng khi quay hướng kia.", "Perisai hanya tampak di lengan yang memakainya: di depan tubuh saat menghadap satu arah, terselip di belakang saat menghadap arah lain.", "โล่แสดงเฉพาะที่แขนที่สวม: บังหน้าลำตัวเมื่อหันทางหนึ่ง ซ่อนอยู่ข้างหลังเมื่อหันอีกทาง", "Kalkanlar yalnızca takıldıkları kolda görünür: bir yöne bakarken gövdenin önünde, öbür yöne bakarken arkanda.", "Los escudos solo se ven en el brazo que los lleva: cruzado ante el cuerpo mirando hacia un lado, escondido detrás mirando hacia el otro.", "Os escudos aparecem só no braço em que estão: na frente do corpo virado para um lado, escondido atrás virado para o outro.", "Щит виден только на той руке, где он надет: перед телом, когда вы смотрите в одну сторону, и за спиной — когда в другую.", "Щит видно лише на тій руці, де він одягнений: перед тілом, коли ви дивитеся в один бік, і за спиною — коли в інший."],
  "The inventory squares are a touch smaller, so all 28 fit without scrolling.": ["持ち物のマスを少し小さくし、28個すべてがスクロールなしで収まるように。", "인벤토리 칸이 살짝 작아져 28칸이 스크롤 없이 모두 들어갑니다.", "背包格子稍微变小了，28 格不用滚动就能全部显示。", "背包格子稍微變小了，28 格不用捲動就能全部顯示。", "Các ô hành trang nhỏ đi một chút, nên cả 28 ô vừa mà không cần cuộn.", "Kotak inventaris sedikit lebih kecil, jadi ke-28 kotak muat tanpa menggulir.", "ช่องเก็บของเล็กลงเล็กน้อย ทั้ง 28 ช่องจึงแสดงได้โดยไม่ต้องเลื่อน", "Envanter kareleri biraz küçüldü, böylece 28'i de kaydırmadan sığıyor.", "Las casillas del inventario son un poco más pequeñas, así que caben las 28 sin desplazar.", "Os espaços do inventário estão um pouco menores, então os 28 cabem sem rolar.", "Ячейки инвентаря стали чуть меньше, и все 28 помещаются без прокрутки.", "Комірки інвентарю стали трохи меншими, і всі 28 вміщуються без прокрутки."],
  "Animations in your Friend's hands": ["フレンドの手のアニメーション", "프렌드 손의 애니메이션", "伙伴手中的动画", "夥伴手中的動畫", "Hoạt ảnh trên tay Bạn của bạn", "Animasi di tangan Sahabatmu", "แอนิเมชันในมือเพื่อนของคุณ", "Dostunun ellerinde animasyonlar", "Animaciones en las manos de tu Amigo", "Animações nas mãos do seu Amigo", "Анимации в руках вашего Друга", "Анімації в руках вашого Друга"],
  "Weapons and tools now move in your Friend's own pixels instead of floating beside it: swords wind up, strike and follow through, staffs thrust forward as a spell leaves, and bows flex.": ["武器や道具は横に浮かぶのではなく、フレンド自身のピクセルの中で動くようになりました：剣は振りかぶって打ち込み振り抜き、杖は呪文が放たれるとき前に突き出し、弓はしなります。", "무기와 도구가 옆에 떠 있는 대신 프렌드의 픽셀 안에서 움직입니다: 검은 치켜들고 내려치고 끝까지 휘두르며, 지팡이는 주문이 나갈 때 앞으로 찌르고, 활은 휘어집니다.", "武器和工具现在在伙伴自己的像素中运动，而不是浮在旁边：剑会蓄势、劈下再收势，法杖在施法时向前一刺，弓会弯曲。", "武器和工具現在在夥伴自己的像素中運動，而不是浮在旁邊：劍會蓄勢、劈下再收勢，法杖在施法時向前一刺，弓會彎曲。", "Vũ khí và dụng cụ giờ chuyển động trong chính các pixel của Bạn thay vì lơ lửng bên cạnh: kiếm vung lên, chém và theo đà, gậy phép đâm tới khi phép bay ra, và cung uốn cong.", "Senjata dan alat kini bergerak di piksel Sahabatmu sendiri alih-alih melayang di sampingnya: pedang mengayun, menebas, dan menuntaskan, tongkat menusuk ke depan saat mantra dilepas, dan busur melentur.", "อาวุธและเครื่องมือตอนนี้ขยับในพิกเซลของเพื่อนคุณเองแทนที่จะลอยอยู่ข้างๆ: ดาบง้าง ฟัน และตามแรง คทาพุ่งไปข้างหน้าเมื่อร่ายคาถา และธนูโค้งงอ", "Silahlar ve aletler artık yanında süzülmek yerine Dostunun kendi piksellerinde hareket ediyor: kılıçlar kalkar, vurur ve savrulur, asalar büyü çıkarken ileri itilir, yaylar esner.", "Las armas y herramientas se mueven ahora en los propios píxeles de tu Amigo en vez de flotar a su lado: las espadas cogen impulso, golpean y siguen el movimiento, los bastones se adelantan al salir el hechizo y los arcos se tensan.", "Armas e ferramentas agora se movem nos próprios pixels do seu Amigo em vez de flutuarem ao lado: espadas tomam impulso, golpeiam e seguem o movimento, cajados avançam quando o feitiço sai e arcos se flexionam.", "Оружие и инструменты теперь двигаются в пикселях самого Друга, а не парят рядом: мечи замахиваются, бьют и доводят удар, посохи выбрасываются вперёд при заклинании, луки изгибаются.", "Зброя й інструменти тепер рухаються в пікселях самого Друга, а не ширяють поруч: мечі замахуються, б'ють і доводять удар, палиці викидаються вперед під час заклинання, луки згинаються."],
  "Axes chop, pickaxes strike the rock, hammers ring on the anvil, rods cast with the line running from the rod's tip, and food is held out over the fire, all drawn in the same pixel style as your gear.": ["斧は伐り、つるはしは岩を打ち、ハンマーは金床に響き、釣り竿は竿先から糸を伸ばして投げ、食べ物は火の上に差し出されます。すべて装備と同じピクセルスタイルで描かれています。", "도끼는 찍고, 곡괭이는 바위를 내리치고, 망치는 모루에 울리고, 낚싯대는 끝에서 줄을 뻗으며 던지고, 음식은 불 위에 내밀어집니다. 모두 장비와 같은 픽셀 스타일로 그렸습니다.", "斧头砍伐，镐敲击岩石，锤子在铁砧上叮当作响，鱼竿抛出时鱼线从竿尖延伸，食物被举在火上，全都以与装备相同的像素风格绘制。", "斧頭砍伐，鎬敲擊岩石，錘子在鐵砧上叮噹作響，魚竿拋出時魚線從竿尖延伸，食物被舉在火上，全都以與裝備相同的像素風格繪製。", "Rìu chặt, cuốc chim bổ vào đá, búa ngân trên đe, cần câu quăng với dây chạy từ đầu cần, và thức ăn được giơ trên lửa, tất cả vẽ cùng phong cách pixel với trang bị.", "Kapak menebang, beliung menghantam batu, palu berdenting di landasan, joran dilempar dengan senar dari ujungnya, dan makanan dipegang di atas api, semuanya digambar dengan gaya piksel yang sama seperti perlengkapanmu.", "ขวานฟัน จอบกระแทกหิน ค้อนดังกังวานบนทั่ง เบ็ดเหวี่ยงโดยสายพุ่งจากปลายคัน และอาหารถูกยื่นเหนือไฟ ทั้งหมดวาดในสไตล์พิกเซลเดียวกับอุปกรณ์", "Baltalar keser, kazmalar kayaya vurur, çekiçler örste çınlar, oltalar ucundan çıkan misinayla atılır ve yemek ateşin üstünde tutulur; hepsi teçhizatınla aynı piksel tarzında çizilmiş.", "Las hachas talan, los picos golpean la roca, los martillos resuenan en el yunque, las cañas lanzan con el sedal saliendo de la punta y la comida se sostiene sobre el fuego, todo dibujado con el mismo estilo de píxeles que tu equipo.", "Machados cortam, picaretas batem na rocha, martelos ressoam na bigorna, varas lançam com a linha saindo da ponta e a comida é segurada sobre o fogo, tudo desenhado no mesmo estilo de pixel do seu equipamento.", "Топоры рубят, кирки бьют по камню, молоты звенят о наковальню, удочки забрасываются с леской от кончика, а еда держится над огнём — всё в том же пиксельном стиле, что и снаряжение.", "Сокири рубають, кайла б'ють по каменю, молоти дзвенять об ковадло, вудки закидаються з волосінню від кінчика, а їжа тримається над вогнем — усе в тому ж піксельному стилі, що й спорядження."],
  "Other players' Friends animate the same way.": ["ほかのプレイヤーのフレンドも同じように動きます。", "다른 플레이어의 프렌드도 같은 방식으로 움직입니다.", "其他玩家的伙伴也以同样的方式动起来。", "其他玩家的夥伴也以同樣的方式動起來。", "Bạn của người chơi khác cũng chuyển động như vậy.", "Sahabat pemain lain juga beranimasi dengan cara yang sama.", "เพื่อนของผู้เล่นอื่นก็ขยับแบบเดียวกัน", "Diğer oyuncuların Dostları da aynı şekilde hareket ediyor.", "Los Amigos de otros jugadores se animan igual.", "Os Amigos dos outros jogadores se animam do mesmo jeito.", "Друзья других игроков анимируются так же.", "Друзі інших гравців анімуються так само."],
  "Multiplayer that gets through": ["つながるマルチプレイ", "연결되는 멀티플레이", "能连上的多人游戏", "能連上的多人遊戲", "Nhiều người chơi luôn kết nối được", "Multipemain yang tembus", "ผู้เล่นหลายคนที่เชื่อมต่อได้", "Ulaşan çok oyunculu", "Multijugador que siempre conecta", "Multijogador que conecta", "Мультиплеер, который пробивается", "Мультиплеєр, що пробивається"],
  "Players on networks that block direct browser-to-browser links can now see each other: the game falls back to passing messages through public relays, so nobody is stuck at 1 online.": ["ブラウザ同士の直接接続をブロックするネットワークのプレイヤーも、互いに見えるようになりました：ゲームが公開リレー経由でメッセージを中継するので、誰も「1人オンライン」で取り残されません。", "브라우저 간 직접 연결을 막는 네트워크의 플레이어도 이제 서로 볼 수 있습니다: 게임이 공개 릴레이로 메시지를 전달하므로 아무도 '1명 접속'에 갇히지 않습니다.", "处于屏蔽浏览器直连网络中的玩家现在也能互相看见：游戏会改用公共中继传递消息，所以没人会卡在「1 人在线」。", "處於封鎖瀏覽器直連網路中的玩家現在也能互相看見：遊戲會改用公共中繼傳遞訊息，所以沒人會卡在「1 人在線」。", "Người chơi trên mạng chặn kết nối trực tiếp giữa các trình duyệt giờ đã thấy nhau: game chuyển sang gửi tin qua các trạm chuyển tiếp công khai, nên không ai bị kẹt ở 1 người online.", "Pemain di jaringan yang memblokir tautan langsung antar-peramban kini bisa saling melihat: game beralih meneruskan pesan lewat relai publik, jadi tak ada yang terjebak di 1 online.", "ผู้เล่นบนเครือข่ายที่บล็อกการเชื่อมต่อตรงระหว่างเบราว์เซอร์ตอนนี้เห็นกันแล้ว: เกมจะส่งข้อความผ่านรีเลย์สาธารณะแทน ไม่มีใครติดอยู่ที่ออนไลน์ 1 คนอีก", "Tarayıcıdan tarayıcıya doğrudan bağlantıyı engelleyen ağlardaki oyuncular artık birbirini görebiliyor: oyun mesajları genel aktarıcılar üzerinden geçirmeye geçiyor, böylece kimse 1 çevrimiçide takılı kalmıyor.", "Los jugadores en redes que bloquean las conexiones directas entre navegadores ya pueden verse: el juego recurre a pasar los mensajes por relés públicos, así que nadie se queda atascado en 1 conectado.", "Jogadores em redes que bloqueiam conexões diretas entre navegadores agora se veem: o jogo passa a enviar as mensagens por retransmissores públicos, então ninguém fica preso em 1 online.", "Игроки в сетях, где заблокированы прямые соединения между браузерами, теперь видят друг друга: игра переключается на передачу сообщений через публичные ретрансляторы, и никто не застревает на «1 в сети».", "Гравці в мережах, де заблоковано прямі з'єднання між браузерами, тепер бачать одне одного: гра перемикається на передачу повідомлень через публічні ретранслятори, і ніхто не застрягає на «1 у мережі»."],
  "Direct links are still used when they work (faster, and private messages stay off the relays). Hover the online badge to see how you're connected.": ["直接接続が使えるときは引き続きそちらを使います（より速く、ささやきはリレーを通りません）。オンラインのバッジにカーソルを合わせると接続方法がわかります。", "직접 연결이 될 때는 계속 그걸 씁니다(더 빠르고, 귓속말은 릴레이를 거치지 않습니다). 접속 배지에 마우스를 올리면 연결 방식이 보입니다.", "直连可用时仍会使用（更快，私聊也不经过中继）。将鼠标悬停在在线标记上可查看连接方式。", "直連可用時仍會使用（更快，私聊也不經過中繼）。將滑鼠懸停在在線標記上可查看連線方式。", "Kết nối trực tiếp vẫn được dùng khi hoạt động (nhanh hơn, và tin nhắn riêng không đi qua trạm chuyển tiếp). Rê chuột lên huy hiệu online để xem bạn kết nối thế nào.", "Tautan langsung tetap dipakai bila berfungsi (lebih cepat, dan pesan pribadi tak lewat relai). Arahkan kursor ke lencana online untuk melihat cara kamu terhubung.", "ยังใช้การเชื่อมต่อตรงเมื่อใช้ได้ (เร็วกว่า และข้อความส่วนตัวไม่ผ่านรีเลย์) วางเมาส์บนป้ายออนไลน์เพื่อดูว่าเชื่อมต่ออย่างไร", "Doğrudan bağlantılar çalıştığında hâlâ kullanılıyor (daha hızlı ve özel mesajlar aktarıcılardan geçmiyor). Nasıl bağlandığını görmek için çevrimiçi rozetinin üzerine gel.", "Las conexiones directas se siguen usando cuando funcionan (más rápidas, y los mensajes privados no pasan por los relés). Pasa el ratón por la insignia de conectados para ver cómo estás conectado.", "As conexões diretas continuam sendo usadas quando funcionam (mais rápidas, e mensagens privadas não passam pelos retransmissores). Passe o mouse no selo de online para ver como você está conectado.", "Прямые соединения по-прежнему используются, когда работают (быстрее, и личные сообщения не идут через ретрансляторы). Наведите курсор на значок «в сети», чтобы увидеть тип соединения.", "Прямі з'єднання й далі використовуються, коли працюють (швидше, і особисті повідомлення не йдуть через ретранслятори). Наведіть курсор на значок «у мережі», щоб побачити тип з'єднання."],
  "First steps, graphics settings and the farm": ["最初の一歩、グラフィック設定、農場", "첫걸음, 그래픽 설정, 농장", "新手指引、图形设置与农场", "新手指引、圖形設定與農場", "Những bước đầu, cài đặt đồ họa và nông trại", "Langkah pertama, pengaturan grafis, dan pertanian", "ก้าวแรก การตั้งค่ากราฟิก และฟาร์ม", "İlk adımlar, grafik ayarları ve çiftlik", "Primeros pasos, ajustes gráficos y la granja", "Primeiros passos, configurações gráficas e a fazenda", "Первые шаги, настройки графики и ферма", "Перші кроки, налаштування графіки та ферма"],
  "New Friends get a guided start: seven quick steps (a tree, a fire, a fish, cooking, the horses, King Hollis, the Realm Daily) with a gold arrow showing the way, and 500 coins and a Lamp of insight at the end. Skippable any time.": ["新しいフレンドにはガイド付きのスタート：金の矢印に導かれる7つの簡単なステップ（木、火、魚、料理、馬、ホリス王、Realm Daily）と、最後に500コインと洞察のランプ。いつでもスキップできます。", "새 프렌드는 안내를 받으며 시작합니다: 금빛 화살표가 길을 알려 주는 일곱 단계(나무, 불, 물고기, 요리, 말, 홀리스 왕, Realm Daily)와 마지막에 500코인과 통찰의 등불. 언제든 건너뛸 수 있습니다.", "新伙伴会获得引导式开局：七个简单步骤（一棵树、一堆火、一条鱼、烹饪、马、霍利斯国王、Realm Daily），金色箭头指路，结束时获得 500 金币和一盏洞察之灯。随时可以跳过。", "新夥伴會獲得引導式開局：七個簡單步驟（一棵樹、一堆火、一條魚、烹飪、馬、霍利斯國王、Realm Daily），金色箭頭指路，結束時獲得 500 金幣和一盞洞察之燈。隨時可以跳過。", "Bạn mới được dẫn dắt khởi đầu: bảy bước nhanh (một cái cây, một đống lửa, một con cá, nấu ăn, những con ngựa, Vua Hollis, Realm Daily) với mũi tên vàng chỉ đường, và 500 xu cùng một Đèn minh triết ở cuối. Có thể bỏ qua bất cứ lúc nào.", "Sahabat baru mendapat awal terpandu: tujuh langkah cepat (pohon, api, ikan, memasak, kuda, Raja Hollis, Realm Daily) dengan panah emas penunjuk jalan, dan 500 koin serta Lampu wawasan di akhir. Bisa dilewati kapan saja.", "เพื่อนใหม่ได้เริ่มต้นแบบมีผู้นำทาง: เจ็ดขั้นตอนสั้นๆ (ต้นไม้ กองไฟ ปลา การทำอาหาร ม้า กษัตริย์ฮอลลิส Realm Daily) มีลูกศรทองชี้ทาง และได้ 500 เหรียญกับตะเกียงแห่งปัญญาในตอนท้าย ข้ามได้ทุกเมื่อ", "Yeni Dostlar rehberli bir başlangıç alıyor: altın bir okun yol gösterdiği yedi hızlı adım (bir ağaç, bir ateş, bir balık, yemek pişirme, atlar, Kral Hollis, Realm Daily) ve sonunda 500 para ile bir İçgörü lambası. İstediğin zaman atlanabilir.", "Los Amigos nuevos tienen un inicio guiado: siete pasos rápidos (un árbol, un fuego, un pez, cocinar, los caballos, el rey Hollis, el Realm Daily) con una flecha dorada que marca el camino, y 500 monedas y una Lámpara de la perspicacia al final. Se puede saltar cuando quieras.", "Amigos novos ganham um início guiado: sete passos rápidos (uma árvore, uma fogueira, um peixe, cozinhar, os cavalos, o rei Hollis, o Realm Daily) com uma seta dourada mostrando o caminho, e 500 moedas e uma Lâmpada da perspicácia no fim. Dá pra pular a qualquer hora.", "Новые Друзья получают обучение: семь быстрых шагов (дерево, костёр, рыба, готовка, лошади, король Холлис, Realm Daily) с золотой стрелкой, указывающей путь, а в конце — 500 монет и Лампа прозрения. Можно пропустить в любой момент.", "Нові Друзі отримують навчання: сім швидких кроків (дерево, вогнище, риба, готування, коні, король Голліс, Realm Daily) із золотою стрілкою, що вказує шлях, а наприкінці — 500 монет і Лампа прозріння. Можна пропустити будь-коли."],
  "Settings → Graphics: Auto, High or Low. Low draws plain ground and walls, skips ambient life and fog, and runs several times faster on older devices. Auto switches to Low by itself if the game runs slowly.": ["設定 → グラフィック：自動・高・低。低は地面と壁をシンプルに描き、環境の生き物や霧を省き、古い端末で数倍速く動きます。自動は、ゲームが重いと自ら低に切り替わります。", "설정 → 그래픽: 자동, 높음, 낮음. 낮음은 바닥과 벽을 단순하게 그리고, 주변 생물과 안개를 생략해 오래된 기기에서 몇 배 빠르게 돌아갑니다. 자동은 게임이 느리면 스스로 낮음으로 바뀝니다.", "设置 → 图形：自动、高或低。低画质绘制朴素的地面和墙壁，省略环境生物和雾气，在旧设备上快好几倍。自动会在游戏运行缓慢时自行切换到低。", "設定 → 圖形：自動、高或低。低畫質繪製樸素的地面和牆壁，省略環境生物和霧氣，在舊裝置上快好幾倍。自動會在遊戲執行緩慢時自行切換到低。", "Cài đặt → Đồ họa: Tự động, Cao hoặc Thấp. Thấp vẽ mặt đất và tường đơn giản, bỏ sinh vật xung quanh và sương mù, chạy nhanh gấp nhiều lần trên máy cũ. Tự động tự chuyển sang Thấp nếu game chạy chậm.", "Pengaturan → Grafis: Otomatis, Tinggi, atau Rendah. Rendah menggambar tanah dan dinding polos, melewatkan kehidupan sekitar dan kabut, dan berjalan beberapa kali lebih cepat di perangkat lama. Otomatis beralih ke Rendah sendiri bila game berjalan lambat.", "ตั้งค่า → กราฟิก: อัตโนมัติ สูง หรือต่ำ ต่ำจะวาดพื้นและกำแพงแบบเรียบ ข้ามสิ่งมีชีวิตรอบๆ และหมอก และเร็วขึ้นหลายเท่าบนอุปกรณ์เก่า อัตโนมัติจะสลับเป็นต่ำเองถ้าเกมช้า", "Ayarlar → Grafik: Otomatik, Yüksek ya da Düşük. Düşük sade zemin ve duvarlar çizer, ortam canlılarını ve sisi atlar, eski cihazlarda birkaç kat hızlı çalışır. Otomatik, oyun yavaşlarsa kendiliğinden Düşük'e geçer.", "Ajustes → Gráficos: Auto, Alto o Bajo. Bajo dibuja suelo y muros simples, omite la fauna ambiental y la niebla, y va varias veces más rápido en dispositivos antiguos. Auto pasa a Bajo por sí solo si el juego va lento.", "Configurações → Gráficos: Auto, Alto ou Baixo. Baixo desenha chão e paredes simples, pula a vida ambiente e a neblina e roda várias vezes mais rápido em aparelhos antigos. Auto muda sozinho para Baixo se o jogo ficar lento.", "Настройки → Графика: Авто, Высокая или Низкая. Низкая рисует простую землю и стены, пропускает живность и туман и работает в разы быстрее на старых устройствах. Авто сама переключается на Низкую, если игра тормозит.", "Налаштування → Графіка: Авто, Висока або Низька. Низька малює просту землю й стіни, пропускає живність і туман і працює в рази швидше на старих пристроях. Авто сама перемикається на Низьку, якщо гра гальмує."],
  "The stables have moved beside the Rare Market, facing the path, with the paddock next door.": ["厩舎はレアマーケットの隣、道に面した場所へ移り、放牧場もその隣にあります。", "마구간이 길을 마주 보는 레어 마켓 옆으로 옮겼고, 방목장도 그 옆에 있습니다.", "马厩搬到了稀有市场旁边，面向小路，隔壁就是围场。", "馬廄搬到了稀有市場旁邊，面向小路，隔壁就是圍場。", "Chuồng ngựa đã dời đến cạnh Chợ hiếm, quay ra lối đi, với bãi quây ngay bên cạnh.", "Kandang kuda pindah ke samping Pasar Langka, menghadap jalan, dengan padang rumput di sebelahnya.", "คอกม้าย้ายไปข้างตลาดหายาก หันหน้าเข้าทางเดิน โดยมีลานล้อมอยู่ติดกัน", "Ahırlar Nadir Pazar'ın yanına, yola bakacak şekilde taşındı; çayır hemen yanında.", "Los establos se han trasladado junto al Mercado raro, frente al camino, con el cercado al lado.", "Os estábulos foram para o lado do Mercado Raro, de frente para a trilha, com o cercado ao lado.", "Конюшни переехали к Редкому рынку, лицом к дороге, а загон — рядом.", "Стайні переїхали до Рідкісного ринку, обличчям до дороги, а загін — поруч."],
  "Hollow Farms: the cows have a new pen out by the windmill, the windmill is rebuilt in stone with lattice sails, there's a new chicken coop, and the miller has a farmhouse.": ["Hollow Farms：牛には風車のそばに新しい囲いができ、風車は格子の羽根を持つ石造りに建て直され、新しい鶏小屋ができ、粉屋には農家ができました。", "Hollow Farms: 소들은 풍차 옆에 새 우리가 생겼고, 풍차는 격자 날개를 단 돌 풍차로 다시 지어졌으며, 새 닭장이 생기고, 방앗간 주인에게는 농가가 생겼습니다.", "Hollow Farms：牛群在风车旁有了新围栏，风车用石头重建并装上格子风帆，还有新的鸡舍，磨坊主也有了农舍。", "Hollow Farms：牛群在風車旁有了新圍欄，風車用石頭重建並裝上格子風帆，還有新的雞舍，磨坊主也有了農舍。", "Hollow Farms: đàn bò có chuồng mới cạnh cối xay gió, cối xay gió được xây lại bằng đá với cánh mắt lưới, có chuồng gà mới, và người xay bột có một trang trại.", "Hollow Farms: sapi punya kandang baru dekat kincir angin, kincir angin dibangun ulang dari batu dengan baling-baling kisi, ada kandang ayam baru, dan penggiling punya rumah pertanian.", "Hollow Farms: วัวมีคอกใหม่ข้างกังหันลม กังหันลมสร้างใหม่ด้วยหินพร้อมใบพัดตาข่าย มีเล้าไก่ใหม่ และคนโม่แป้งมีบ้านไร่", "Hollow Farms: inekler yel değirmeninin yanında yeni bir ağıla kavuştu, yel değirmeni kafes kanatlarla taştan yeniden yapıldı, yeni bir kümes var ve değirmencinin bir çiftlik evi oldu.", "Hollow Farms: las vacas tienen un corral nuevo junto al molino, el molino se ha reconstruido en piedra con aspas de celosía, hay un gallinero nuevo y el molinero tiene una casa de labranza.", "Hollow Farms: as vacas ganharam um curral novo perto do moinho, o moinho foi reconstruído em pedra com velas de treliça, há um galinheiro novo e o moleiro tem uma casa de fazenda.", "Hollow Farms: у коров новый загон у мельницы, мельница отстроена в камне с решётчатыми крыльями, есть новый курятник, а у мельника — фермерский дом.", "Hollow Farms: у корів новий загін біля млина, млин відбудовано з каменю з ґратчастими крилами, є новий курник, а в мельника — фермерський дім."],
  "World boss, duels, pets and achievements": ["ワールドボス、決闘、ペット、実績", "월드 보스, 결투, 펫, 업적", "世界首领、决斗、宠物与成就", "世界首領、決鬥、寵物與成就", "Trùm thế giới, đấu tay đôi, thú cưng và thành tựu", "Bos dunia, duel, peliharaan, dan pencapaian", "บอสโลก การดวล สัตว์เลี้ยง และความสำเร็จ", "Dünya patronu, düellolar, evcil hayvanlar ve başarımlar", "Jefe mundial, duelos, mascotas y logros", "Chefe mundial, duelos, mascotes e conquistas", "Мировой босс, дуэли, питомцы и достижения", "Світовий бос, дуелі, улюбленці та досягнення"],
  "The Ashen Colossus rises in Wyrmreach every two hours (on the even UTC hours) for twenty minutes. It takes a crowd, and everyone who wounds it shares the loot.": ["Ashen Colossus はワームリーチに2時間ごと（UTCの偶数時）に20分間現れます。大勢で挑む必要があり、傷を負わせた全員で戦利品を分け合います。", "Ashen Colossus가 웜리치에 2시간마다(UTC 짝수 시) 20분 동안 나타납니다. 여럿이 함께 싸워야 하고, 상처를 입힌 모두가 전리품을 나눕니다.", "Ashen Colossus 每两小时（UTC 偶数整点）在龙域出现二十分钟。需要一群人合力，所有伤到它的人共享战利品。", "Ashen Colossus 每兩小時（UTC 偶數整點）在龍域出現二十分鐘。需要一群人合力，所有傷到它的人共享戰利品。", "Ashen Colossus trỗi dậy ở Wyrmreach mỗi hai giờ (vào giờ chẵn UTC) trong hai mươi phút. Cần cả đám đông, và ai làm nó bị thương đều được chia chiến lợi phẩm.", "Ashen Colossus bangkit di Wyrmreach setiap dua jam (pada jam genap UTC) selama dua puluh menit. Butuh keramaian, dan semua yang melukainya berbagi jarahan.", "Ashen Colossus ปรากฏที่เวิร์มรีชทุกสองชั่วโมง (ชั่วโมงคู่ตาม UTC) นานยี่สิบนาที ต้องรวมพลกันสู้ และทุกคนที่ทำร้ายมันได้แบ่งของรางวัล", "Ashen Colossus her iki saatte bir (çift UTC saatlerinde) yirmi dakikalığına Wyrmreach'te yükselir. Kalabalık ister ve onu yaralayan herkes ganimeti paylaşır.", "El Ashen Colossus se alza en Wyrmreach cada dos horas (en las horas pares UTC) durante veinte minutos. Hace falta un grupo, y todos los que lo hieren se reparten el botín.", "O Ashen Colossus surge em Wyrmreach a cada duas horas (nas horas pares UTC) por vinte minutos. Precisa de uma multidão, e todos que o ferem dividem o saque.", "Ashen Colossus поднимается в Вирмриче каждые два часа (по чётным часам UTC) на двадцать минут. Нужна толпа, и все, кто его ранил, делят добычу.", "Ashen Colossus підіймається у Вірмрічі щодві години (у парні години UTC) на двадцять хвилин. Потрібен натовп, і всі, хто його поранив, ділять здобич."],
  "The Sparring Ring, east of Market Street: step inside and right-click another player to Fight. Duels are safe: nobody dies or loses items, and wins are counted.": ["Market Street の東にある Sparring Ring：中に入ってほかのプレイヤーを右クリックし「戦う」。決闘は安全で、誰も死なずアイテムも失わず、勝利数が記録されます。", "Market Street 동쪽의 Sparring Ring: 안으로 들어가 다른 플레이어를 우클릭해 '싸우기'. 결투는 안전합니다: 아무도 죽거나 아이템을 잃지 않고, 승리가 기록됩니다.", "Market Street 东边的 Sparring Ring：走进去右键另一名玩家选择「战斗」。决斗很安全：没人会死或丢失物品，胜场会被记录。", "Market Street 東邊的 Sparring Ring：走進去右鍵另一名玩家選擇「戰鬥」。決鬥很安全：沒人會死或遺失物品，勝場會被記錄。", "Sparring Ring, phía đông Market Street: bước vào và nhấp chuột phải vào người chơi khác để Chiến đấu. Đấu tay đôi an toàn: không ai chết hay mất đồ, và số trận thắng được đếm.", "Sparring Ring, di timur Market Street: masuk dan klik kanan pemain lain untuk Bertarung. Duel aman: tak ada yang mati atau kehilangan barang, dan kemenangan dihitung.", "Sparring Ring ทางตะวันออกของ Market Street: ก้าวเข้าไปแล้วคลิกขวาผู้เล่นอื่นเพื่อต่อสู้ การดวลปลอดภัย: ไม่มีใครตายหรือเสียไอเท็ม และนับชัยชนะ", "Market Street'in doğusundaki Sparring Ring: içeri gir ve Dövüşmek için başka bir oyuncuya sağ tıkla. Düellolar güvenli: kimse ölmez ya da eşya kaybetmez, galibiyetler sayılır.", "El Sparring Ring, al este de Market Street: entra y haz clic derecho en otro jugador para Luchar. Los duelos son seguros: nadie muere ni pierde objetos, y las victorias se cuentan.", "O Sparring Ring, a leste da Market Street: entre e clique com o botão direito em outro jogador para Lutar. Os duelos são seguros: ninguém morre nem perde itens, e as vitórias são contadas.", "Sparring Ring к востоку от Market Street: войдите и кликните правой кнопкой по другому игроку, чтобы сразиться. Дуэли безопасны: никто не умирает и не теряет предметы, а победы засчитываются.", "Sparring Ring на схід від Market Street: зайдіть і клацніть правою кнопкою по іншому гравцю, щоб битися. Дуелі безпечні: ніхто не гине й не втрачає предметів, а перемоги зараховуються."],
  "Six pets to find while you train: Stumpy (woodcutting), Pebble (mining), Bubbles (fishing), Mote (Sigilcraft), Emberling (dragons) and Cinderkin (the Colossus). Call them from the Friends tab.": ["修行中に見つかる6匹のペット：Stumpy（木こり）、Pebble（採掘）、Bubbles（釣り）、Mote（印章術）、Emberling（ドラゴン）、Cinderkin（Colossus）。フレンドタブから呼び出せます。", "훈련하며 찾을 수 있는 펫 여섯: Stumpy(벌목), Pebble(채광), Bubbles(낚시), Mote(인장술), Emberling(드래곤), Cinderkin(Colossus). 친구 탭에서 부를 수 있습니다.", "训练时可以找到六只宠物：Stumpy（伐木）、Pebble（采矿）、Bubbles（钓鱼）、Mote（印记术）、Emberling（巨龙）和 Cinderkin（Colossus）。在好友标签页中召唤它们。", "訓練時可以找到六隻寵物：Stumpy（伐木）、Pebble（採礦）、Bubbles（釣魚）、Mote（印記術）、Emberling（巨龍）和 Cinderkin（Colossus）。在好友分頁中召喚牠們。", "Sáu thú cưng tìm được khi luyện tập: Stumpy (đốn gỗ), Pebble (khai mỏ), Bubbles (câu cá), Mote (Ấn thuật), Emberling (rồng) và Cinderkin (Colossus). Gọi chúng từ thẻ Bạn bè.", "Enam peliharaan untuk ditemukan saat berlatih: Stumpy (menebang), Pebble (menambang), Bubbles (memancing), Mote (Seni Sigil), Emberling (naga), dan Cinderkin (Colossus). Panggil dari tab Teman.", "สัตว์เลี้ยงหกตัวที่หาได้ระหว่างฝึก: Stumpy (ตัดไม้) Pebble (ขุดแร่) Bubbles (ตกปลา) Mote (ศิลปะผนึก) Emberling (มังกร) และ Cinderkin (Colossus) เรียกได้จากแท็บเพื่อน", "Antrenman yaparken bulunacak altı evcil hayvan: Stumpy (odunculuk), Pebble (madencilik), Bubbles (balıkçılık), Mote (Mühürcülük), Emberling (ejderhalar) ve Cinderkin (Colossus). Arkadaşlar sekmesinden çağır.", "Seis mascotas que encontrar mientras entrenas: Stumpy (tala), Pebble (minería), Bubbles (pesca), Mote (Sigilería), Emberling (dragones) y Cinderkin (el Colossus). Llámalas desde la pestaña de Amigos.", "Seis mascotes para encontrar enquanto treina: Stumpy (corte de lenha), Pebble (mineração), Bubbles (pesca), Mote (Selaria), Emberling (dragões) e Cinderkin (o Colossus). Chame-os pela aba de Amigos.", "Шесть питомцев, которых можно найти за тренировками: Stumpy (рубка), Pebble (добыча), Bubbles (рыбалка), Mote (Печатное дело), Emberling (драконы) и Cinderkin (Colossus). Вызывайте их со вкладки «Друзья».", "Шість улюбленців, яких можна знайти під час тренувань: Stumpy (рубання), Pebble (видобуток), Bubbles (риболовля), Mote (Печатне ремесло), Emberling (дракони) і Cinderkin (Colossus). Викликайте їх із вкладки «Друзі»."],
  "Achievements: 32 to earn, on a new tab of this popup, and counted on your adventurer card.": ["実績：獲得できる実績は32個。このポップアップの新しいタブにあり、冒険者カードにも数が表示されます。", "업적: 얻을 수 있는 업적 32개. 이 팝업의 새 탭에 있고, 모험가 카드에도 집계됩니다.", "成就：共有 32 个可获得，在这个弹窗的新标签页中，并计入你的冒险者卡片。", "成就：共有 32 個可獲得，在這個彈窗的新分頁中，並計入你的冒險者卡片。", "Thành tựu: 32 cái để đạt, ở thẻ mới của cửa sổ này, và được đếm trên thẻ nhà thám hiểm của bạn.", "Pencapaian: 32 untuk diraih, di tab baru pada popup ini, dan dihitung di kartu petualangmu.", "ความสำเร็จ: 32 รายการให้ได้รับ ในแท็บใหม่ของหน้าต่างนี้ และนับลงบัตรนักผจญภัยของคุณ", "Başarımlar: kazanılacak 32 tane, bu pencerenin yeni bir sekmesinde ve maceracı kartında sayılıyor.", "Logros: 32 por conseguir, en una pestaña nueva de esta ventana, y contados en tu tarjeta de aventurero.", "Conquistas: 32 para ganhar, numa nova aba desta janela, e contadas no seu cartão de aventureiro.", "Достижения: 32 штуки, на новой вкладке этого окна, и они учитываются в вашей карточке искателя приключений.", "Досягнення: 32 штуки, на новій вкладці цього вікна, і вони враховуються у вашій картці шукача пригод."],
  "Hiscores in the Friends tab: you ranked with every player you've met.": ["フレンドタブにランキング：これまで出会った全プレイヤーと順位を比べられます。", "친구 탭의 랭킹: 만난 모든 플레이어와 순위를 매깁니다.", "好友标签页中的排行榜：你与遇到过的每位玩家一同排名。", "好友分頁中的排行榜：你與遇到過的每位玩家一同排名。", "Bảng xếp hạng ở thẻ Bạn bè: bạn được xếp hạng cùng mọi người chơi bạn từng gặp.", "Papan skor di tab Teman: peringkatmu bersama setiap pemain yang pernah kau temui.", "อันดับคะแนนในแท็บเพื่อน: จัดอันดับคุณกับผู้เล่นทุกคนที่เคยพบ", "Arkadaşlar sekmesinde skor tablosu: tanıştığın her oyuncuyla birlikte sıralanırsın.", "Clasificación en la pestaña de Amigos: tu puesto junto a todos los jugadores que has conocido.", "Ranking na aba de Amigos: você classificado com todos os jogadores que conheceu.", "Рекорды на вкладке «Друзья»: ваше место среди всех игроков, которых вы встречали.", "Рекорди на вкладці «Друзі»: ваше місце серед усіх гравців, яких ви зустрічали."],
  "Level-up fireworks that everyone nearby sees. Hoofbeats, dust and a whinny when you ride. Footprints in snow and sand, splashes in the bog. Rare drops shine with a beam of light and a chime.": ["近くの全員に見えるレベルアップの花火。騎乗中は蹄の音、土ぼこり、いななき。雪と砂に足跡、沼には水しぶき。レアドロップは光の柱とチャイムで輝きます。", "근처 모두가 보는 레벨 업 불꽃놀이. 탈 때는 말발굽 소리, 먼지, 말 울음. 눈과 모래에 발자국, 늪에서는 물보라. 희귀 드롭은 빛기둥과 종소리로 빛납니다.", "附近所有人都能看到的升级烟花。骑乘时有马蹄声、尘土和嘶鸣。雪地和沙地上有脚印，沼泽里有水花。稀有掉落会伴随光柱和铃声闪耀。", "附近所有人都能看到的升級煙火。騎乘時有馬蹄聲、塵土和嘶鳴。雪地和沙地上有腳印，沼澤裡有水花。稀有掉落會伴隨光柱和鈴聲閃耀。", "Pháo hoa lên cấp mà mọi người gần đó đều thấy. Tiếng vó, bụi và tiếng hí khi cưỡi ngựa. Dấu chân trên tuyết và cát, nước bắn tung trong đầm lầy. Đồ rơi hiếm tỏa sáng với một cột sáng và tiếng chuông.", "Kembang api naik level yang terlihat semua orang di sekitar. Derap kuda, debu, dan ringkikan saat berkuda. Jejak kaki di salju dan pasir, cipratan di rawa. Jarahan langka bersinar dengan seberkas cahaya dan denting.", "ดอกไม้ไฟเลเวลอัปที่ทุกคนใกล้ๆ เห็น เสียงกีบม้า ฝุ่น และเสียงร้องเมื่อขี่ รอยเท้าบนหิมะและทราย น้ำกระเซ็นในบึง ของดรอปหายากเปล่งแสงพร้อมลำแสงและเสียงกริ๊ง", "Yakındaki herkesin gördüğü seviye atlama havai fişekleri. Binerken nal sesleri, toz ve kişneme. Karda ve kumda ayak izleri, bataklıkta su sıçramaları. Nadir ganimetler bir ışık huzmesi ve çın sesiyle parlar.", "Fuegos artificiales al subir de nivel que ven todos los que están cerca. Cascos, polvo y relinchos al cabalgar. Huellas en la nieve y la arena, salpicaduras en la ciénaga. Los botines raros brillan con un haz de luz y un tintineo.", "Fogos de artifício ao subir de nível que todos por perto veem. Cascos, poeira e relincho quando você cavalga. Pegadas na neve e na areia, respingos no pântano. Drops raros brilham com um feixe de luz e um sininho.", "Фейерверк при повышении уровня, который видят все рядом. Стук копыт, пыль и ржание при езде. Следы на снегу и песке, брызги в болоте. Редкая добыча сияет лучом света и звоном.", "Феєрверк при підвищенні рівня, який бачать усі поруч. Стукіт копит, пил та іржання під час їзди. Сліди на снігу й піску, бризки в болоті. Рідкісна здобич сяє променем світла й дзвоном."],
  "When a friend near you emotes, your Friend joins in.": ["近くの友達がエモートすると、あなたのフレンドも一緒にやります。", "근처 친구가 이모트를 하면 당신의 프렌드도 함께합니다.", "当你附近的好友做表情动作时，你的伙伴也会一起做。", "當你附近的好友做表情動作時，你的夥伴也會一起做。", "Khi một người bạn gần bạn biểu cảm, Bạn của bạn cũng làm theo.", "Saat teman di dekatmu ber-emote, Sahabatmu ikut serta.", "เมื่อเพื่อนใกล้ๆ ทำท่าทาง เพื่อนของคุณจะทำตามด้วย", "Yakınındaki bir arkadaş ifade yaptığında Dostun da katılır.", "Cuando un amigo cercano hace un gesto, tu Amigo se une.", "Quando um amigo perto faz um emote, seu Amigo entra junto.", "Когда друг рядом показывает эмоцию, ваш Друг подхватывает.", "Коли друг поруч показує емоцію, ваш Друг підхоплює."],
  "Daily streaks and this log": ["連続ログインとこのログ", "연속 접속과 이 기록", "每日连续登录与这份日志", "每日連續登入與這份日誌", "Chuỗi ngày đăng nhập và nhật ký này", "Rentetan harian dan log ini", "สตรีครายวันและบันทึกนี้", "Günlük seriler ve bu günlük", "Rachas diarias y este registro", "Sequências diárias e este registro", "Ежедневные серии и этот журнал", "Щоденні серії та цей журнал"],
  "Log in every day for a streak reward on a seven-day cycle, up to a Lamp of insight and 5,000 coins on day 7. Each full week adds 25% to the coins.": ["毎日ログインすると7日周期の連続報酬がもらえ、7日目には洞察のランプと5,000コイン。1週間続くごとにコインが25%増えます。", "매일 접속하면 7일 주기 연속 보상을 받고, 7일째엔 통찰의 등불과 5,000코인. 한 주를 채울 때마다 코인이 25% 늘어납니다.", "每天登录可获得七天一循环的连续奖励，第 7 天最高可得一盏洞察之灯和 5,000 金币。每满一周金币增加 25%。", "每天登入可獲得七天一循環的連續獎勵，第 7 天最高可得一盞洞察之燈和 5,000 金幣。每滿一週金幣增加 25%。", "Đăng nhập mỗi ngày để nhận thưởng chuỗi theo chu kỳ bảy ngày, đến một Đèn minh triết và 5.000 xu vào ngày 7. Mỗi tuần trọn vẹn cộng thêm 25% xu.", "Masuk setiap hari untuk hadiah rentetan dalam siklus tujuh hari, hingga Lampu wawasan dan 5.000 koin di hari ke-7. Setiap minggu penuh menambah 25% koin.", "เข้าเกมทุกวันเพื่อรับรางวัลสตรีครอบเจ็ดวัน สูงสุดคือตะเกียงแห่งปัญญาและ 5,000 เหรียญในวันที่ 7 ทุกสัปดาห์ที่ครบเพิ่มเหรียญ 25%", "Yedi günlük döngüde seri ödülü için her gün giriş yap; 7. günde bir İçgörü lambası ve 5.000 paraya kadar. Her tam hafta paralara %25 ekler.", "Entra cada día para una recompensa de racha en un ciclo de siete días, hasta una Lámpara de la perspicacia y 5.000 monedas el día 7. Cada semana completa suma un 25 % a las monedas.", "Entre todo dia para ganhar a recompensa de sequência num ciclo de sete dias, até uma Lâmpada da perspicácia e 5.000 moedas no dia 7. Cada semana completa soma 25% às moedas.", "Заходите каждый день за наградой серии по семидневному циклу — до Лампы прозрения и 5000 монет на 7-й день. Каждая полная неделя добавляет 25% к монетам.", "Заходьте щодня по нагороду серії за семиденним циклом — до Лампи прозріння і 5000 монет на 7-й день. Кожен повний тиждень додає 25% до монет."],
  "Three daily challenges, the same for everyone: gain XP in two skills and defeat some monsters. Finish all three to open the daily chest.": ["全員共通の3つのデイリーチャレンジ：2つのスキルで経験値を稼ぎ、モンスターを倒す。3つすべてを終えるとデイリー宝箱が開きます。", "모두에게 같은 일일 도전 셋: 두 스킬에서 경험치를 얻고 몬스터를 처치하세요. 셋을 다 끝내면 일일 상자가 열립니다.", "三个每日挑战，人人相同：在两项技能中获得经验并击败一些怪物。全部完成即可打开每日宝箱。", "三個每日挑戰，人人相同：在兩項技能中獲得經驗並擊敗一些怪物。全部完成即可打開每日寶箱。", "Ba thử thách hằng ngày, giống nhau cho mọi người: nhận XP ở hai kỹ năng và hạ vài quái vật. Hoàn thành cả ba để mở rương hằng ngày.", "Tiga tantangan harian, sama untuk semua: dapatkan XP di dua keahlian dan kalahkan beberapa monster. Selesaikan ketiganya untuk membuka peti harian.", "ภารกิจรายวันสามอย่าง เหมือนกันทุกคน: รับ XP ในสองทักษะและกำจัดมอนสเตอร์ ทำครบทั้งสามเพื่อเปิดหีบรายวัน", "Herkes için aynı üç günlük görev: iki beceride XP kazan ve birkaç canavar yen. Günlük sandığı açmak için üçünü de bitir.", "Tres desafíos diarios, iguales para todos: gana XP en dos habilidades y derrota a algunos monstruos. Completa los tres para abrir el cofre diario.", "Três desafios diários, iguais para todos: ganhe XP em duas habilidades e derrote alguns monstros. Termine os três para abrir o baú diário.", "Три ежедневных испытания, одинаковые для всех: получите опыт в двух навыках и победите монстров. Выполните все три, чтобы открыть ежедневный сундук.", "Три щоденні випробування, однакові для всіх: здобудьте досвід у двох навичках і переможіть монстрів. Виконайте всі три, щоб відкрити щоденну скриню."],
  "This Updates tab: see what's changed after every update. Reopen it any time with the button by the minimap.": ["このアップデートタブ：アップデートのたびに変更点がわかります。ミニマップ横のボタンでいつでも開けます。", "이 업데이트 탭: 업데이트마다 무엇이 바뀌었는지 확인하세요. 미니맵 옆 버튼으로 언제든 다시 열 수 있습니다.", "这个更新标签页：每次更新后都能看到改动。随时可以用小地图旁的按钮重新打开。", "這個更新分頁：每次更新後都能看到改動。隨時可以用小地圖旁的按鈕重新打開。", "Thẻ Cập nhật này: xem những gì đã thay đổi sau mỗi bản cập nhật. Mở lại bất cứ lúc nào bằng nút cạnh bản đồ nhỏ.", "Tab Pembaruan ini: lihat apa yang berubah setelah setiap pembaruan. Buka lagi kapan saja dengan tombol di samping peta mini.", "แท็บอัปเดตนี้: ดูว่ามีอะไรเปลี่ยนหลังการอัปเดตแต่ละครั้ง เปิดใหม่ได้ทุกเมื่อด้วยปุ่มข้างมินิแมป", "Bu Güncellemeler sekmesi: her güncellemeden sonra neyin değiştiğini gör. Mini haritanın yanındaki düğmeyle istediğin zaman yeniden aç.", "Esta pestaña de Novedades: mira qué ha cambiado tras cada actualización. Vuelve a abrirla cuando quieras con el botón junto al minimapa.", "Esta aba de Atualizações: veja o que mudou após cada atualização. Reabra quando quiser pelo botão ao lado do minimapa.", "Эта вкладка обновлений: смотрите, что изменилось после каждого обновления. Открыть снова можно кнопкой у мини-карты.", "Ця вкладка оновлень: дивіться, що змінилося після кожного оновлення. Відкрити знову можна кнопкою біля мінімапи."],
  "Your adventurer card shows your Friend exactly as in the Realm: helm, cape, shield, weapon, and the mount you're riding.": ["冒険者カードにはレルムでの姿そのままのフレンドが表示されます：兜、マント、盾、武器、そして乗っている騎乗動物。", "모험가 카드가 렐름에서의 모습 그대로 프렌드를 보여 줍니다: 투구, 망토, 방패, 무기, 타고 있는 탈것까지.", "冒险者卡片会如实展示你在王国中的伙伴：头盔、披风、盾牌、武器以及你骑的坐骑。", "冒險者卡片會如實展示你在王國中的夥伴：頭盔、披風、盾牌、武器以及你騎的坐騎。", "Thẻ nhà thám hiểm hiển thị Bạn của bạn y như trong Vương quốc: mũ giáp, áo choàng, khiên, vũ khí và thú cưỡi bạn đang cưỡi.", "Kartu petualangmu menampilkan Sahabatmu persis seperti di Realm: helm, jubah, perisai, senjata, dan tunggangan yang kau naiki.", "บัตรนักผจญภัยแสดงเพื่อนของคุณตรงตามในอาณาจักร: หมวกเกราะ ผ้าคลุม โล่ อาวุธ และพาหนะที่ขี่อยู่", "Maceracı kartın Dostunu tam Diyar'daki gibi gösterir: miğfer, pelerin, kalkan, silah ve bindiğin binek.", "Tu tarjeta de aventurero muestra a tu Amigo tal como está en el Reino: yelmo, capa, escudo, arma y la montura que llevas.", "Seu cartão de aventureiro mostra seu Amigo exatamente como no Reino: elmo, capa, escudo, arma e a montaria que você está usando.", "Карточка искателя приключений показывает Друга точно таким, как в Королевстве: шлем, плащ, щит, оружие и скакун.", "Картка шукача пригод показує Друга точнісінько таким, як у Королівстві: шолом, плащ, щит, зброя та скакун."],
  "A one-minute trailer at the top of the website.": ["ウェブサイトの一番上に1分間のトレーラー。", "웹사이트 맨 위에 1분짜리 트레일러.", "网站顶部有一段一分钟的预告片。", "網站頂部有一段一分鐘的預告片。", "Một đoạn trailer dài một phút ở đầu trang web.", "Trailer satu menit di bagian atas situs web.", "ตัวอย่างความยาวหนึ่งนาทีที่ด้านบนสุดของเว็บไซต์", "Web sitesinin en üstünde bir dakikalık fragman.", "Un tráiler de un minuto en lo alto de la web.", "Um trailer de um minuto no topo do site.", "Минутный трейлер в самом верху сайта.", "Хвилинний трейлер на самому верху сайту."],
  "The Friendhollow stables": ["フレンドホロウの厩舎", "프렌드할로우 마구간", "友谷的马厩", "友谷的馬廄", "Chuồng ngựa Friendhollow", "Kandang kuda Friendhollow", "คอกม้าเฟรนด์ฮอลโลว์", "Friendhollow ahırları", "Los establos de Friendhollow", "Os estábulos de Friendhollow", "Конюшни Френдхоллоу", "Стайні Френдголлоу"],
  "Marigold's stables, west of the castle, sell eight mounts for RF: six horses and two unicorns. Horses and a unicorn graze in the paddock.": ["城の西にあるマリーゴールドの厩舎では、RFで8頭の騎乗動物を販売：馬6頭とユニコーン2頭。放牧場では馬とユニコーンが草を食んでいます。", "성 서쪽의 마리골드 마구간에서 RF로 탈것 여덟을 팝니다: 말 여섯과 유니콘 둘. 방목장에선 말과 유니콘이 풀을 뜯습니다.", "城堡西边的 Marigold 马厩用 RF 出售八匹坐骑：六匹马和两匹独角兽。围场里有马和一匹独角兽在吃草。", "城堡西邊的 Marigold 馬廄用 RF 出售八匹坐騎：六匹馬和兩匹獨角獸。圍場裡有馬和一匹獨角獸在吃草。", "Chuồng ngựa của Marigold, phía tây lâu đài, bán tám thú cưỡi bằng RF: sáu ngựa và hai kỳ lân. Ngựa và một kỳ lân gặm cỏ trong bãi quây.", "Kandang Marigold, di barat kastel, menjual delapan tunggangan dengan RF: enam kuda dan dua unicorn. Kuda dan satu unicorn merumput di padang.", "คอกม้าของแมรีโกลด์ ทางตะวันตกของปราสาท ขายพาหนะแปดตัวด้วย RF: ม้าหกตัวและยูนิคอร์นสองตัว ม้ากับยูนิคอร์นหนึ่งตัวกินหญ้าอยู่ในลาน", "Kalenin batısındaki Marigold'un ahırları RF karşılığında sekiz binek satıyor: altı at ve iki tek boynuzlu at. Çayırda atlar ve bir tek boynuzlu at otluyor.", "Los establos de Marigold, al oeste del castillo, venden ocho monturas por RF: seis caballos y dos unicornios. Caballos y un unicornio pastan en el cercado.", "Os estábulos da Marigold, a oeste do castelo, vendem oito montarias por RF: seis cavalos e dois unicórnios. Cavalos e um unicórnio pastam no cercado.", "Конюшни Мэриголд к западу от замка продают за RF восемь скакунов: шесть лошадей и двух единорогов. В загоне пасутся лошади и единорог.", "Стайні Мерігольд на захід від замку продають за RF вісім скакунів: шість коней і двох єдинорогів. У загоні пасуться коні та єдиноріг."],
  "Riding carries you two or three tiles a tick without using run energy, and every mount has a gift: healing, faster gathering, more coins, Defence, XP or light in the dark.": ["騎乗すると走力を使わずに1ティックで2〜3マス進め、どの騎乗動物にも恩恵があります：回復、採集の高速化、コイン増加、防御、経験値、暗闇の明かり。", "타고 다니면 달리기 기력 없이 한 틱에 두세 칸을 가고, 모든 탈것에 선물이 있습니다: 회복, 더 빠른 채집, 더 많은 코인, 방어, 경험치, 어둠 속 빛.", "骑乘时每刻移动两三格且不消耗奔跑体力，每匹坐骑都有一项天赋：治疗、更快采集、更多金币、防御、经验或黑暗中的光。", "騎乘時每刻移動兩三格且不消耗奔跑體力，每匹坐騎都有一項天賦：治療、更快採集、更多金幣、防禦、經驗或黑暗中的光。", "Cưỡi đi được hai hay ba ô mỗi nhịp mà không tốn năng lượng chạy, và mỗi thú cưỡi có một món quà: hồi máu, thu thập nhanh hơn, thêm xu, Phòng thủ, XP hoặc ánh sáng trong bóng tối.", "Berkuda membawamu dua atau tiga petak per tik tanpa memakai energi lari, dan setiap tunggangan punya anugerah: penyembuhan, mengumpulkan lebih cepat, lebih banyak koin, Pertahanan, XP, atau cahaya dalam gelap.", "การขี่พาไปสองหรือสามช่องต่อจังหวะโดยไม่ใช้พลังวิ่ง และพาหนะทุกตัวมีของขวัญ: รักษา เก็บของเร็วขึ้น เหรียญมากขึ้น ป้องกัน XP หรือแสงในความมืด", "Binmek, koşu enerjisi harcamadan seni her tikte iki üç kare taşır ve her bineğin bir armağanı vardır: iyileştirme, daha hızlı toplama, daha çok para, Savunma, XP ya da karanlıkta ışık.", "Cabalgar te mueve dos o tres casillas por tic sin gastar energía de carrera, y cada montura tiene un don: curación, recolección más rápida, más monedas, Defensa, XP o luz en la oscuridad.", "Cavalgar leva você dois ou três blocos por tique sem gastar energia de corrida, e toda montaria tem um dom: cura, coleta mais rápida, mais moedas, Defesa, XP ou luz no escuro.", "Верхом вы проходите две-три клетки за тик без траты энергии бега, и у каждого скакуна есть дар: лечение, быстрый сбор, больше монет, Защита, опыт или свет во тьме.", "Верхи ви проходите дві-три клітинки за тік без витрати енергії бігу, і кожен скакун має дар: лікування, швидший збір, більше монет, Захист, досвід або світло в темряві."],
  "Ride or dismount with the saddle button by the run orb, or H. Other players see you riding, and ridden towards you, your mount's head is in front of you.": ["走るオーブの横の鞍ボタンか H キーで乗り降り。ほかのプレイヤーにも騎乗姿が見え、こちらへ向かって走るときは騎乗動物の頭があなたの前に来ます。", "달리기 구슬 옆 안장 버튼이나 H로 타고 내립니다. 다른 플레이어도 타고 있는 모습을 보며, 당신 쪽으로 달려올 땐 탈것의 머리가 당신 앞에 옵니다.", "用奔跑球旁的马鞍按钮或 H 键骑乘或下马。其他玩家能看到你骑乘，朝你骑来时坐骑的头在你前面。", "用奔跑球旁的馬鞍按鈕或 H 鍵騎乘或下馬。其他玩家能看到你騎乘，朝你騎來時坐騎的頭在你前面。", "Cưỡi hoặc xuống bằng nút yên ngựa cạnh quả cầu chạy, hoặc phím H. Người chơi khác thấy bạn cưỡi, và khi cưỡi về phía bạn, đầu thú cưỡi ở phía trước bạn.", "Naik atau turun dengan tombol pelana di samping bola lari, atau H. Pemain lain melihatmu berkuda, dan saat berkuda ke arahmu, kepala tungganganmu ada di depanmu.", "ขี่หรือลงด้วยปุ่มอานข้างลูกแก้ววิ่ง หรือปุ่ม H ผู้เล่นอื่นเห็นคุณขี่ และเมื่อขี่เข้าหาคุณ หัวพาหนะจะอยู่ด้านหน้าคุณ", "Koşu kürenin yanındaki eyer düğmesiyle ya da H ile bin veya in. Diğer oyuncular seni binerken görür, sana doğru sürüldüğünde bineğinin başı önündedir.", "Monta o desmonta con el botón de la silla junto al orbe de carrera, o con H. Los demás jugadores te ven montar, y cuando cabalgas hacia ellos, la cabeza de tu montura va delante de ti.", "Monte ou desmonte com o botão de sela ao lado do orbe de corrida, ou H. Outros jogadores veem você montado, e quando vem na direção deles, a cabeça da montaria fica à sua frente.", "Садитесь и спешивайтесь кнопкой седла у шара бега или клавишей H. Другие игроки видят вас верхом, а когда вы едете к ним, голова скакуна впереди вас.", "Сідайте й спішуйтеся кнопкою сідла біля кулі бігу або клавішею H. Інші гравці бачать вас верхи, а коли ви їдете до них, голова скакуна попереду вас."],
  "Gear you can see": ["見える装備", "보이는 장비", "看得见的装备", "看得見的裝備", "Trang bị nhìn thấy được", "Perlengkapan yang terlihat", "อุปกรณ์ที่มองเห็น", "Görülebilen teçhizat", "Equipo a la vista", "Equipamento visível", "Видимое снаряжение", "Видиме спорядження"],
  "Helms, hats, shields and weapons are painted into your Friend's own pixels and move with you: blades in a ready guard, staffs upright with their orb, bows held by the grip, axes on the shoulder.": ["兜、帽子、盾、武器がフレンド自身のピクセルに描き込まれ、一緒に動きます：剣は構えの姿勢、杖はオーブを上にまっすぐ、弓は握りを持ち、斧は肩に。", "투구, 모자, 방패, 무기가 프렌드의 픽셀에 그려져 함께 움직입니다: 칼날은 준비 자세로, 지팡이는 구슬을 위로 곧게, 활은 손잡이를 쥐고, 도끼는 어깨에.", "头盔、帽子、盾牌和武器都画进了伙伴自己的像素里，随你一起移动：刀刃摆出预备架势，法杖竖直托着法球，弓握在握把处，斧头扛在肩上。", "頭盔、帽子、盾牌和武器都畫進了夥伴自己的像素裡，隨你一起移動：刀刃擺出預備架勢，法杖豎直托著法球，弓握在握把處，斧頭扛在肩上。", "Mũ giáp, mũ, khiên và vũ khí được vẽ vào chính pixel của Bạn và di chuyển cùng bạn: lưỡi kiếm ở thế thủ, gậy phép dựng thẳng với quả cầu, cung cầm ở tay nắm, rìu vác trên vai.", "Helm, topi, perisai, dan senjata dilukis ke piksel Sahabatmu dan bergerak bersamamu: bilah dalam kuda-kuda siaga, tongkat tegak dengan bolanya, busur dipegang di gagangnya, kapak di bahu.", "หมวกเกราะ หมวก โล่ และอาวุธวาดลงในพิกเซลของเพื่อนคุณและขยับไปด้วย: ใบมีดอยู่ในท่าเตรียม คทาตั้งตรงพร้อมลูกแก้ว ธนูถือที่ด้าม ขวานพาดบ่า", "Miğferler, şapkalar, kalkanlar ve silahlar Dostunun kendi piksellerine boyanmış ve seninle hareket ediyor: kılıçlar hazır duruşta, asalar küreleriyle dik, yaylar tutamaktan tutulmuş, baltalar omuzda.", "Yelmos, sombreros, escudos y armas están pintados en los propios píxeles de tu Amigo y se mueven contigo: hojas en guardia, bastones erguidos con su orbe, arcos sujetos por la empuñadura y hachas al hombro.", "Elmos, chapéus, escudos e armas são pintados nos próprios pixels do seu Amigo e se movem com você: lâminas em guarda, cajados erguidos com o orbe, arcos segurados pela empunhadura, machados no ombro.", "Шлемы, шляпы, щиты и оружие нарисованы прямо в пикселях Друга и двигаются вместе с вами: клинки в стойке, посохи стоймя с навершием, луки за рукоять, топоры на плече.", "Шоломи, капелюхи, щити й зброю намальовано просто в пікселях Друга, і вони рухаються разом із вами: клинки в стійці, палиці сторч із навершям, луки за руків'я, сокири на плечі."],
  "Weapons swing free only mid-attack.": ["武器が大きく振られるのは攻撃中だけです。", "무기는 공격 중에만 자유롭게 휘둘러집니다.", "武器只在攻击过程中才会自由挥动。", "武器只在攻擊過程中才會自由揮動。", "Vũ khí chỉ vung tự do khi đang tấn công.", "Senjata hanya berayun bebas saat menyerang.", "อาวุธจะเหวี่ยงอิสระเฉพาะตอนโจมตี", "Silahlar yalnızca saldırı sırasında serbestçe savrulur.", "Las armas solo se balancean libremente en mitad de un ataque.", "As armas só balançam livres no meio do ataque.", "Оружие свободно раскачивается только во время атаки.", "Зброя вільно розгойдується лише під час атаки."],
};
